                        <button className="w-full h-full p-4 bg-slate-900/50 border border-white/5 rounded-2xl hover:bg-slate-800 hover:border-white/20 transition-all text-left group">
                            <FileJson className="w-6 h-6 text-slate-400 mb-3 group-hover:text-emerald-400 transition-colors" />
                            <h4 className="font-bold text-white text-sm mb-1">Restore Protocol</h4>
                            <p className="text-xs text-slate-500 font-medium">Import external backup capsule.</p>
                        </button>
                    </div>
                </div>

                <div className="mt-4 pt-4 border-t border-white/5">
                     <button 
                        onClick={() => setShowConfirmModal('reset')}
                        className="w-full p-4 bg-rose-950/10 border border-rose-500/10 rounded-2xl hover:bg-rose-950/20 hover:border-rose-500/30 transition-all text-left group flex items-center justify-between"
                    >
                        <div>
                            <h4 className="font-bold text-rose-400 text-sm mb-1">Nuclear Reset</h4>
                            <p className="text-xs text-rose-500/60 font-medium">Wipe all nodes and financial identity.</p>
                        </div>
                        <Trash2 className="w-5 h-5 text-rose-500/50 group-hover:text-rose-400 transition-colors" />
                    </button>
                </div>
            </div>
        </div>
      </div>

      {/* Confirmation Modal for Reset/Downgrade */}
      {showConfirmModal && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/90 backdrop-blur-xl animate-fade-in">
             <div className="relative max-w-sm w-full bg-slate-950 rounded-[2rem] border border-white/10 shadow-[0_0_100px_rgba(244,63,94,0.3)] overflow-hidden animate-slide-up ring-1 ring-white/5">
                 <div className="p-8 text-center">
                     <div className="w-16 h-16 rounded-full bg-rose-500/20 flex items-center justify-center mx-auto mb-6 ring-1 ring-rose-500/50 animate-pulse">
                        <AlertTriangle className="w-8 h-8 text-rose-500" />
                     </div>
                     <h3 className="text-2xl font-black text-white mb-2 uppercase tracking-tight">Security Check</h3>
                     <p className="text-rose-200 text-sm mb-6 leading-relaxed font-medium">
                         {showConfirmModal === 'reset' ? 'This will permanently purge all financial data.' : 'Downgrading removes access to premium AI features immediately.'}
                     </p>

                     <div className="mb-6 text-left">
                         <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">
                             {localStorage.getItem('nova_vault_key') ? "Confirm Passcode" : "Authorization Required"}
                         </label>
                         <input 
                            type="password" 
                            autoFocus
                            value={confirmPassword}
                            onChange={(e) => { setConfirmPassword(e.target.value); setPasswordError(''); }}
                            onKeyDown={(e) => handleConfirmKeyDown(e, () => {
                                if (showConfirmModal === 'reset') onClearData();
                                if (showConfirmModal === 'downgrade' && onDowngrade) onDowngrade();
                            })}
                            placeholder={localStorage.getItem('nova_vault_key') ? "Enter vault password" : "Type 'CONFIRM'"}
                            className="w-full bg-slate-900 border border-white/10 rounded-xl p-3 text-white mt-1 focus:border-rose-500 focus:outline-none"
                         />
                         {passwordError && <p className="text-rose-500 text-xs mt-2 font-bold">{passwordError}</p>}
                         {!localStorage.getItem('nova_vault_key') && (
                             <p className="text-slate-500 text-[10px] mt-2 italic">Social Login? Type 'CONFIRM' to proceed.</p>
                         )}
                     </div>

                     <div className="grid grid-cols-2 gap-3">
                        <button 
                            onClick={() => {
                                setShowConfirmModal(null);
                                setConfirmPassword('');
                                setPasswordError('');
                            }} 
                            className="py-3 bg-slate-800 hover:bg-slate-700 text-white font-bold rounded-xl transition-colors border border-white/5"
                        >
                             Cancel
                        </button>
                        <button 
                            onClick={() => verifyPasswordAndExecute(() => {
                                if (showConfirmModal === 'reset') onClearData();
                                if (showConfirmModal === 'downgrade' && onDowngrade) onDowngrade();
                            })}
                            className="py-3 bg-rose-600 hover:bg-rose-500 text-white font-bold rounded-xl shadow-[0_0_20px_rgba(244,63,94,0.4)] active:scale-95 transition-all flex items-center justify-center gap-2"
                        >
                             <Trash2 className="w-4 h-4" /> Confirm
                        </button>
                     </div>
                 </div>
             </div>
        </div>
      )}

    </div>
  );
};

export default Settings;

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { Account, Budget, Goal, Transaction, UserPlan, ToastMessage, BotMode, Currency, Language, TransactionType, SpendingPeriod, SpendingStatus } from '../types';
import { ACCOUNTS, INITIAL_TRANSACTIONS, INITIAL_BUDGETS, INITIAL_GOALS, NAV_ITEMS, TRANSLATIONS } from './constants';
import { evaluateSpending } from './services/ruleEngine';
import Dashboard from './components/Dashboard';
import Transactions from './components/Transactions';
import Accounts from './components/Accounts';
import Insights from './components/Insights';
import Goals from './components/Goals';
import Plans from './components/Plans';
import Settings from './components/Settings';
import ScenarioSandbox from './components/ScenarioSandbox';
import UpcomingFeatures from './components/UpcomingFeatures';
import CashflowBeta from './components/CashflowBeta';
import BillNegotiator from './components/BillNegotiator';
import LandingPage from './components/LandingPage';
import OnboardingModal from './components/OnboardingModal';
import ToastContainer from './components/Toast';
import FloatingAssistant from './components/FloatingAssistant';
import Investment from './components/Investment';
import { Sparkles, LogOut, MessageCircle, Zap, Crown, AlertTriangle, ShieldX, Terminal, ArrowRight, Eye, EyeOff, Shield, Lock } from 'lucide-react';

const getMonthlyUsage = (key: string) => {
    try {
        const item = localStorage.getItem(key);
        if (!item) return 0;
        const parsed = JSON.parse(item);
        const now = new Date();
        if (parsed.month !== now.getMonth() || parsed.year !== now.getFullYear()) return 0;
        return parsed.count || 0;
    } catch (e) { return 0; }
};

const safeSetItem = (key: string, value: string) => {
    try { localStorage.setItem(key, value); } catch (e) { console.warn(`Storage quota exceeded for ${key}`); }
};

// Feature IDs for Pin System
const PINNABLE_FEATURES = ['budget-monitor', 'sandbox-link', 'goal-tracker', 'system-alerts', 'neural-quota'];

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isPrivacyMode, setIsPrivacyMode] = useState(() => localStorage.getItem('nova_privacy_mode') === 'true');
  const [isPinMode, setIsPinMode] = useState(false);
  const [autoScanTrigger, setAutoScanTrigger] = useState(false);

  // Onboarding & Enforcement State
  const [onboardingComplete, setOnboardingComplete] = useState(() => localStorage.getItem('nova_onboarding_complete') === 'true');

  // Fix: Ensure spendingLimit is always a valid number to prevent NaN
  const [spendingLimit, setSpendingLimit] = useState<number>(() => {
      const stored = localStorage.getItem('nova_spending_limit');
      if (!stored) return 1000;
      const parsed = parseFloat(stored);
      // Strict check: if parsed is NaN or infinite, fallback to 1000
      return Number.isFinite(parsed) && parsed > 0 ? parsed : 1000;
  });

  const [spendingPeriod, setSpendingPeriod] = useState<SpendingPeriod>(() => (localStorage.getItem('nova_spending_period') as SpendingPeriod) || 'monthly');

  // Pin System State
  const [pinnedIds, setPinnedIds] = useState<string[]>(() => {
    try {
        const saved = localStorage.getItem('nova_pinned_ids');
        return saved ? JSON.parse(saved) : []; 
    } catch { return []; }
  });

  const [featureUsage, setFeatureUsage] = useState<Record<string, number>>(() => {
      try {
          const saved = localStorage.getItem('nova_feature_usage');
          return saved ? JSON.parse(saved) : {};
      } catch { return {}; }
  });

  const [accounts, setAccounts] = useState<Account[]>(() => {
      const saved = localStorage.getItem('nova_accounts');
      return saved ? JSON.parse(saved) : ACCOUNTS;
  });
  const [transactions, setTransactions] = useState<Transaction[]>(() => {
      const saved = localStorage.getItem('nova_transactions');
      return saved ? JSON.parse(saved) : INITIAL_TRANSACTIONS;
  });
  const [budgets, setBudgets] = useState<Budget[]>(() => {
      const saved = localStorage.getItem('nova_budgets');
      return saved ? JSON.parse(saved) : INITIAL_BUDGETS;
  });
  const [goals, setGoals] = useState<Goal[]>(() => {
      const saved = localStorage.getItem('nova_goals');
      return saved ? JSON.parse(saved) : INITIAL_GOALS;
  });

  const [userPlan, setUserPlan] = useState<UserPlan>(() => localStorage.getItem('nova_user_plan') as UserPlan || 'free');
  const [insightUsage, setInsightUsage] = useState(() => getMonthlyUsage('nova_insight_usage'));
  const [scanUsage, setScanUsage] = useState(() => getMonthlyUsage('nova_scan_usage'));
  const [negotiationUsage, setNegotiationUsage] = useState(() => getMonthlyUsage('nova_negotiation_usage'));

  const [isLoggedIn, setIsLoggedIn] = useState(() => localStorage.getItem('nova_auth_token') !== null);
  const [isLogoutModalOpen, setIsLogoutModalOpen] = useState(false);
  const [toasts, setToasts] = useState<ToastMessage[]>([]);
  const [botMode, setBotMode] = useState<BotMode>(() => (localStorage.getItem('nova_bot_mode') as BotMode) || 'ruthless');
  const [pendingChatQuery, setPendingChatQuery] = useState<string | null>(null);

  // User Profile State with Proper Initialization
  const [userName, setUserName] = useState(() => localStorage.getItem('nova_user_name') || 'Pilot');
  const [userEmail, setUserEmail] = useState(() => localStorage.getItem('nova_user_email') || 'pilot@nova.io');
  const [userAvatar, setUserAvatar] = useState(() => localStorage.getItem('nova_user_avatar') || '');
  const [userAvatarZoom, setUserAvatarZoom] = useState(() => parseFloat(localStorage.getItem('nova_user_avatar_zoom') || '1'));
  const [userAvatarPos, setUserAvatarPos] = useState(() => {
      try {
          const saved = localStorage.getItem('nova_user_avatar_pos');
          return saved ? JSON.parse(saved) : { x: 0, y: 0 };
      } catch { return { x: 0, y: 0 }; }
  });
  const [userBorder, setUserBorder] = useState(() => localStorage.getItem('nova_user_border') || 'default');
  const [userBackground, setUserBackground] = useState(() => localStorage.getItem('nova_user_bg') || '');

  const [currency, setCurrency] = useState<Currency>(() => (localStorage.getItem('nova_currency') as Currency) || 'USD');
  const [language, setLanguage] = useState<Language>(() => (localStorage.getItem('nova_language') as Language) || 'en');

  // Persistence Effects - Data
  useEffect(() => safeSetItem('nova_accounts', JSON.stringify(accounts)), [accounts]);
  useEffect(() => safeSetItem('nova_transactions', JSON.stringify(transactions)), [transactions]);
  useEffect(() => safeSetItem('nova_budgets', JSON.stringify(budgets)), [budgets]);
  useEffect(() => safeSetItem('nova_goals', JSON.stringify(goals)), [goals]);

  // Persistence Effects - Settings & Profile
  useEffect(() => safeSetItem('nova_user_plan', userPlan), [userPlan]);
  useEffect(() => safeSetItem('nova_currency', currency), [currency]);
  useEffect(() => safeSetItem('nova_language', language), [language]);
  useEffect(() => safeSetItem('nova_bot_mode', botMode), [botMode]);
  useEffect(() => safeSetItem('nova_privacy_mode', isPrivacyMode.toString()), [isPrivacyMode]);
  useEffect(() => safeSetItem('nova_pinned_ids', JSON.stringify(pinnedIds)), [pinnedIds]);
  useEffect(() => safeSetItem('nova_feature_usage', JSON.stringify(featureUsage)), [featureUsage]);
  useEffect(() => safeSetItem('nova_spending_limit', spendingLimit.toString()), [spendingLimit]);
  useEffect(() => safeSetItem('nova_spending_period', spendingPeriod), [spendingPeriod]);
  useEffect(() => safeSetItem('nova_onboarding_complete', onboardingComplete.toString()), [onboardingComplete]);

  // Persistence Effects - User Identity (Ensure robust saving)
  useEffect(() => {
      localStorage.setItem('nova_user_name', userName);
  }, [userName]);
  useEffect(() => {
      localStorage.setItem('nova_user_email', userEmail);
  }, [userEmail]);
  useEffect(() => {
      if(userAvatar) safeSetItem('nova_user_avatar', userAvatar);
  }, [userAvatar]);
  useEffect(() => safeSetItem('nova_user_avatar_zoom', userAvatarZoom.toString()), [userAvatarZoom]);
  useEffect(() => safeSetItem('nova_user_avatar_pos', JSON.stringify(userAvatarPos)), [userAvatarPos]);
  useEffect(() => safeSetItem('nova_user_border', userBorder), [userBorder]);
  useEffect(() => safeSetItem('nova_user_bg', userBackground), [userBackground]);

  // Spending Enforcement Calculation (Zero AI, Pure Math)
  const spendingStatus: { currentSpend: number; status: SpendingStatus } = useMemo(() => {
      const now = new Date();
      let startDate = new Date();

      if (spendingPeriod === 'weekly') {
          // Set to previous Sunday (or today if Sunday)
          const day = now.getDay();
          const diff = now.getDate() - day;
          startDate = new Date(now.setDate(diff));
          startDate.setHours(0, 0, 0, 0);
      } else {
          // Set to 1st of current month
          startDate = new Date(now.getFullYear(), now.getMonth(), 1);
      }

      const currentSpend = transactions
          .filter(t => t.type === TransactionType.EXPENSE && new Date(t.date) >= startDate)
          .reduce((acc, t) => acc + t.amount, 0);

      const status = evaluateSpending(currentSpend, spendingLimit);
      return { currentSpend, status };
  }, [transactions, spendingPeriod, spendingLimit]);

  // Usage counters
  useEffect(() => {
      const now = new Date();
      const meta = { month: now.getMonth(), year: now.getFullYear(), count: insightUsage };
      safeSetItem('nova_insight_usage', JSON.stringify(meta));
  }, [insightUsage]);

  useEffect(() => {
      const now = new Date();
      const meta = { month: now.getMonth(), year: now.getFullYear(), count: scanUsage };
      safeSetItem('nova_scan_usage', JSON.stringify(meta));
  }, [scanUsage]);

  useEffect(() => {
      const now = new Date();
      const meta = { month: now.getMonth(), year: now.getFullYear(), count: negotiationUsage };
      safeSetItem('nova_negotiation_usage', JSON.stringify(meta));
  }, [negotiationUsage]);

  const addToast = useCallback((message: string, type: 'success' | 'error' | 'info' = 'info') => {
    setToasts(prev => [...prev, { id: Date.now().toString(), message, type }]);
  }, []);

  const trackFeatureUsage = useCallback((featureId: string) => {
      setFeatureUsage(prev => ({
          ...prev,
          [featureId]: (prev[featureId] || 0) + 1
      }));
  }, []);

  // Auto-Pin Heuristic
  useEffect(() => {
      if (!isLoggedIn) return;
      const hasAutoPinned = localStorage.getItem('nova_has_auto_pinned');
      if (hasAutoPinned) return;

      const totalActions = (Object.values(featureUsage) as number[]).reduce((a, b) => a + b, 0);
      if (totalActions > 10) {
          const sorted = Object.entries(featureUsage)
              .filter(([key]) => PINNABLE_FEATURES.includes(key))
              .sort((a, b) => (b[1] as number) - (a[1] as number))
              .map(([key]) => key)
              .slice(0, 2); 

          if (sorted.length > 0) {
              setPinnedIds(sorted);
              addToast(`System optimization complete. Top ${sorted.length} modules pinned.`, 'info');
              localStorage.setItem('nova_has_auto_pinned', 'true');
          }
      }
  }, [featureUsage, isLoggedIn, addToast]);

  const handleTogglePin = (id: string) => {
    setPinnedIds(prev => {
        if (prev.includes(id)) {
            return prev.filter(p => p !== id);
        }
        const limit = userPlan === 'ultra' ? 5 : userPlan === 'pro' ? 3 : 1;
        if (prev.length >= limit) {
            addToast(`Slot Limit Reached (${limit}). Unpin a module to replace.`, 'error');
            return prev;
        }
        return [...prev, id];
    });
  };

  const handleToggleStealth = useCallback(() => {
    if (userPlan !== 'ultra') {
        addToast('Stealth Protocol is an Elite-exclusive feature.', 'info');
        setActiveTab('plans');
        return;
    }
    setIsPrivacyMode(prev => !prev);
    addToast(`Stealth Protocol ${!isPrivacyMode ? 'Engaged' : 'Disengaged'}`, 'info');
  }, [userPlan, isPrivacyMode, addToast]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
        const isModI = (e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'i';
        if (isModI) {
            e.preventDefault();
            setIsPinMode(prev => {
                const newVal = !prev;
                addToast(newVal ? 'Pin Configuration Mode: ACTIVE' : 'Pin Configuration Mode: END', 'info');
                if (newVal) setActiveTab('dashboard');
                return newVal;
            });
        }
        if (e.key === 'Escape' && isPinMode) {
            setIsPinMode(false);
            addToast('Pin Configuration Mode: END', 'info');
        }
        if (e.shiftKey && e.key.toLowerCase() === 'p') {
            handleToggleStealth();
        }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isPinMode, handleToggleStealth, addToast]);

  const removeToast = (id: string) => {
    setToasts(prev => prev.filter(t => t.id !== id));
  };

  const formatCurrency = (amount: number) => {
    const safeAmount = isNaN(amount) ? 0 : amount;
    const val = new Intl.NumberFormat(language === 'vi' ? 'vi-VN' : 'en-US', { 
        style: 'currency', currency: currency,
    }).format(safeAmount);

    if (isPrivacyMode && userPlan === 'ultra') {
        return <span className="blur-md opacity-50 bg-white/5 px-1 rounded-md">{val.replace('-', '')}</span>;
    }
    return val;
  };

  const reconcileBalance = (tx: Transaction, direction: 'add' | 'delete') => {
      if (tx.accountId === 'manual') return;
      setAccounts(prev => prev.map(acc => {
          if (acc.id === tx.accountId) {
              const isIncome = tx.type === TransactionType.INCOME;
              let change = tx.amount;
              if (direction === 'add') change = isIncome ? change : -change;
              else change = isIncome ? -change : change;
              return { ...acc, balance: acc.balance + change };
          }
          return acc;
      }));
  };

  const handleAddTransaction = (t: Transaction) => {
      setTransactions(prev => [t, ...prev]);
      reconcileBalance(t, 'add');
      addToast('Transaction recorded.', 'success');
  };

  const handleDeleteTransaction = (id: string) => {
      const tx = transactions.find(t => t.id === id);
      if (tx) {
          reconcileBalance(tx, 'delete');
          setTransactions(prev => prev.filter(t => t.id !== id));
          addToast('Transaction purged.', 'info');
      }
  };

  const handleLogin = (name: string) => {
    setIsLoggedIn(true);
    setUserName(name);
    localStorage.setItem('nova_user_name', name);
  };

  const confirmLogout = () => {
    localStorage.removeItem('nova_auth_token');
    setIsLoggedIn(false);
    setIsLogoutModalOpen(false);
  };

  const handleAskCoach = (message?: string) => {
    if (message) {
      setPendingChatQuery(message);
    }
    setActiveTab('insights');
  };

  const handleNavigate = (tab: string, params?: any) => {
    if (params?.autoScan) setAutoScanTrigger(true);
    setActiveTab(tab);
  };

  const handleOnboardingComplete = (name: string, lang: Language, per: SpendingPeriod, lim: number) => {
      const validName = name && name.trim().length > 0 ? name : 'Commander';
      setUserName(validName);
      localStorage.setItem('nova_user_name', validName);

      setLanguage(lang);
      setSpendingPeriod(per);

      const validLimit = Number.isFinite(lim) && lim > 0 ? lim : 1000;
      setSpendingLimit(validLimit);
      localStorage.setItem('nova_spending_limit', validLimit.toString());

      setOnboardingComplete(true);
      addToast(`Welcome, ${validName}. Systems online.`, 'success');
  };

  const branding = useMemo(() => {
    switch (userPlan) {
      case 'ultra':
        return {
          bg: 'bg-gradient-to-tr from-indigo-600 to-purple-600',
          shadow: 'shadow-indigo-500/40',
          icon: <Sparkles className="w-6 h-6 text-white" />,
          label: 'Elite Terminal'
        };
      case 'pro':
        return {
          bg: 'bg-gradient-to-tr from-amber-400 to-orange-500',
          shadow: 'shadow-amber-500/40',
          icon: <Zap className="w-6 h-6 text-white" />,
          label: 'Pro Uplink'
        };
      default:
        return {
          bg: 'bg-slate-800',
          shadow: 'shadow-black/20',
          icon: <Shield className="w-6 h-6 text-slate-400" />,
          label: 'Free Tier'
        };
    }
  }, [userPlan]);

  if (!isLoggedIn) return <LandingPage onLoginSuccess={handleLogin} />;

  if (!onboardingComplete) return <OnboardingModal onComplete={handleOnboardingComplete} />;

  return (
    <div 
      className={`flex h-screen bg-[#020617] text-slate-100 font-sans selection:bg-indigo-500/30 overflow-hidden relative ${isPinMode ? 'cursor-default' : ''}`}
      style={userBackground ? { backgroundImage: `url(${userBackground})`, backgroundSize: 'cover', backgroundPosition: 'center', backgroundAttachment: 'fixed' } : {}}
    >
      {/* Atmosphere Overlay - Adjusted opacity to 40% to allow background to shine through */}
      {userBackground && (
          <div className="absolute inset-0 bg-slate-950/40 z-0 pointer-events-none backdrop-blur-[1px]"></div>
      )}

      <FloatingAssistant transactions={transactions} budgets={budgets} userPlan={userPlan} botMode={botMode} isVisible={activeTab !== 'insights'} onOpenChat={handleAskCoach} insightUsage={insightUsage} />

      <aside className="hidden md:flex flex-col w-64 p-4 pb-8 z-20 bg-slate-950/40 backdrop-blur-md border-r border-white/5 relative">
        <div className="flex items-center gap-3 px-4 py-3 mb-8 shrink-0">
            <div className={`w-10 h-10 rounded-xl flex items-center justify-center shadow-lg ring-1 ring-white/10 ${branding.bg} ${branding.shadow}`}>{branding.icon}</div>
            <div><h1 className="text-xl font-bold tracking-tight text-white">Nova AI</h1><p className={`text-[10px] font-bold uppercase tracking-wider ${userPlan === 'ultra' ? 'text-purple-400' : userPlan === 'pro' ? 'text-amber-400' : 'text-slate-500'}`}>{branding.label}</p></div>
        </div>
        <nav className="flex-1 space-y-1 overflow-y-auto custom-scrollbar pr-1">
            {NAV_ITEMS.map((item) => {
                const isActive = activeTab === item.id;
                const label = TRANSLATIONS[language]?.[item.id as keyof typeof TRANSLATIONS['en']] || item.label;
                return (
                    <button key={item.id} onClick={() => setActiveTab(item.id)} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-bold transition-all duration-300 group ${isActive ? 'bg-indigo-600/10 text-indigo-400 shadow-[0_0_20px_rgba(99,102,241,0.15)] ring-1 ring-indigo-500/20' : 'text-slate-400 hover:text-white hover:bg-white/5'}`}>
                        <item.icon className={`w-5 h-5 transition-colors ${isActive ? 'text-indigo-400' : 'text-slate-500 group-hover:text-white'}`} />{label}
                    </button>
                );
            })}
        </nav>
        <div className="mt-auto pt-6 border-t border-white/5 shrink-0">
             <button onClick={handleToggleStealth} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all mb-2 ${isPrivacyMode && userPlan === 'ultra' ? 'bg-indigo-500/20 text-indigo-400 border border-indigo-500/30' : 'text-slate-500 hover:text-slate-300 hover:bg-white/5'}`}>
                {isPrivacyMode ? <EyeOff className="w-5 h-5" /> : <Shield className="w-5 h-5" />} {isPrivacyMode ? 'Stealth Engaged' : 'Stealth Protocol'}
             </button>
             <button onClick={() => setActiveTab('settings')} className="w-full text-left px-4 py-4 rounded-2xl bg-slate-900/50 border border-white/5 flex items-center gap-3 mb-4 hover:bg-slate-800 transition-colors group">
                 <div className="w-10 h-10 rounded-full bg-indigo-500 flex items-center justify-center text-white overflow-hidden relative border border-white/10 shadow-inner">{userAvatar ? <img src={userAvatar} className="w-full h-full object-cover" alt="User" /> : <span className="font-bold text-lg">{userName.charAt(0)}</span>}</div>
                 <div className="overflow-hidden"><h4 className="font-bold text-white text-sm truncate group-hover:text-indigo-400 transition-colors">{userName}</h4><p className="text-[10px] text-slate-500 truncate font-bold uppercase tracking-widest">{userPlan} tier</p></div>
             </button>
             <button onClick={() => setIsLogoutModalOpen(true)} className="w-full flex items-center gap-2 px-4 py-2 mb-4 text-xs font-bold text-slate-500 hover:text-rose-400 transition-colors uppercase tracking-widest"><LogOut className="w-4 h-4" /> Sign Out</button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 z-10 relative overflow-hidden">
        {isPinMode && (
          <div className="absolute inset-0 z-[100] bg-black/40 backdrop-blur-[2px] pointer-events-none flex flex-col items-center justify-start pt-20">
              <div className="bg-indigo-600/90 text-white font-black text-xs uppercase tracking-[0.3em] px-8 py-4 rounded-2xl shadow-[0_0_50px_rgba(99,102,241,0.5)] border border-indigo-400/50 animate-pulse pointer-events-auto">
                  Pin Mode Active :: Select Priority Nodes :: Esc to Exit
              </div>
          </div>
        )}

        <div className="flex-1 overflow-y-auto p-4 md:p-8 pb-24 md:pb-8 custom-scrollbar">
            {activeTab === 'dashboard' && <Dashboard userName={userName} accounts={accounts} transactions={transactions} goals={goals} budgets={budgets} onNavigate={handleNavigate} onAddAccount={() => setActiveTab('accounts')} onAddTransaction={() => setActiveTab('transactions')} onAddGoal={() => setActiveTab('goals')} formatCurrency={formatCurrency} userPlan={userPlan} onAskCoach={handleAskCoach} isPinMode={isPinMode} pinnedIds={pinnedIds} onTogglePin={handleTogglePin} trackEvent={trackFeatureUsage} insightUsage={insightUsage} spendingStatus={spendingStatus.status} currentPeriodSpend={spendingStatus.currentSpend} spendingLimit={spendingLimit} spendingPeriod={spendingPeriod} />}
            {activeTab === 'transactions' && <Transactions transactions={transactions} accounts={accounts} onDelete={handleDeleteTransaction} onAdd={handleAddTransaction} formatCurrency={formatCurrency} onNavigateToAccounts={() => setActiveTab('accounts')} userPlan={userPlan} scanUsage={scanUsage} onIncrementScan={() => setScanUsage(prev => prev + 1)} currency={currency} />}
            {activeTab === 'accounts' && <Accounts accounts={accounts} budgets={budgets} transactions={transactions} userPlan={userPlan} onAdd={(acc) => { setAccounts(prev => [...prev, acc]); addToast('Account linked.', 'success'); }} onUpdate={(acc) => { setAccounts(prev => prev.map(a => a.id === acc.id ? acc : a)); addToast('Account updated.', 'success'); }} onDelete={(id) => { setAccounts(prev => prev.filter(a => a.id !== id)); setTransactions(prev => prev.map(t => t.accountId === id ? { ...t, accountId: 'manual' } : t)); addToast('Account removed.', 'info'); }} formatCurrency={formatCurrency} userName={userName} userAvatar={userAvatar} userAvatarZoom={userAvatarZoom} userAvatarPos={userAvatarPos} userBorder={userBorder} onNavigate={handleNavigate} />}
            {activeTab === 'cashflow' && <CashflowBeta transactions={transactions} accounts={accounts} goals={goals} formatCurrency={formatCurrency} userPlan={userPlan} />}
            {activeTab === 'negotiator' && <BillNegotiator userPlan={userPlan} onIncrementUsage={() => setNegotiationUsage(prev => prev + 1)} negotiationUsage={negotiationUsage} transactions={transactions} />}
            {activeTab === 'insights' && <Insights transactions={transactions} userPlan={userPlan} onUpgradeClick={() => setActiveTab('plans')} formatCurrency={formatCurrency} insightUsage={insightUsage} onIncrementUsage={() => setInsightUsage(prev => prev + 1)} onApplyBudgets={(newBudgets) => { const existingCats = new Set(budgets.map(b => b.category)); const toAdd = newBudgets.filter(b => !existingCats.has(b.category)); setBudgets(prev => [...prev, ...toAdd]); addToast(`Applied ${toAdd.length} AI limits.`, 'success'); }} initialPrompt={pendingChatQuery} onPromptHandled={() => setPendingChatQuery(null)} botMode={botMode} onNavigate={handleNavigate} onAddGoal={(g) => { setGoals(prev => [...prev, g]); addToast('Goal created from proposal.', 'success'); }} goals={goals} budgets={budgets} autoScanTriggered={autoScanTrigger} />}
            {activeTab === 'sandbox' && <ScenarioSandbox transactions={transactions} goals={goals} formatCurrency={formatCurrency} userPlan={userPlan} onUpgradeClick={() => setActiveTab('plans')} insightUsage={insightUsage} onIncrementUsage={(val) => setInsightUsage(prev => prev + (val || 1))} />}
            {activeTab === 'goals' && <Goals goals={goals} budgets={budgets} transactions={transactions} onAddGoal={(g) => { setGoals(prev => [...prev, g]); addToast('Goal deployed.', 'success'); }} onUpdateGoal={(g) => { setGoals(prev => prev.map(goal => goal.id === g.id ? g : goal)); addToast('Goal updated.', 'success'); }} onAddBudget={(b) => { setBudgets(prev => [...prev, b]); addToast('Limit set.', 'success'); }} onDeleteBudget={(id) => { setBudgets(prev => prev.filter(b => b.id !== id)); addToast('Limit removed.', 'info'); }} formatCurrency={formatCurrency} />}
            {activeTab === 'plans' && <Plans currentPlan={userPlan} onUpgrade={(plan) => { setUserPlan(plan); addToast(`Plan upgraded.`, 'success'); }} onDowngrade={() => { setUserPlan('free'); addToast('Plan reset.', 'info'); }} onNavigateDashboard={() => setActiveTab('dashboard')} />}
            {activeTab === 'investment' && <Investment accounts={accounts} formatCurrency={formatCurrency} userPlan={userPlan} />}
            {activeTab === 'upcoming' && <UpcomingFeatures />}
            {activeTab === 'settings' && <Settings userName={userName} userEmail={userEmail} userAvatar={userAvatar} userAvatarZoom={userAvatarZoom} userAvatarPos={userAvatarPos} userBorder={userBorder} userBackground={userBackground} onUpdateBackground={setUserBackground} userPlan={userPlan} onUpdateProfile={(n, e, a, z, p, b) => { 
                // Immediate manual save to ensure persistence
                localStorage.setItem('nova_user_name', n);
                localStorage.setItem('nova_user_email', e);
                if (a) localStorage.setItem('nova_user_avatar', a);

                setUserName(n); 
                setUserEmail(e); 
                setUserAvatar(a); 
                setUserAvatarZoom(z); 
                setUserAvatarPos(p); 
                setUserBorder(b); 
                addToast('Profile updated.', 'success'); 
            }} addToast={addToast} onExportData={() => addToast('Exporting...')} onImportData={() => addToast('Importing...')} onClearData={() => addToast('Clearing...')} language={language} onUpdateLanguage={setLanguage} currency={currency} onUpdateCurrency={setCurrency} botMode={botMode} onUpdateBotMode={setBotMode} spendingLimit={spendingLimit} onUpdateSpendingLimit={setSpendingLimit} spendingPeriod={spendingPeriod} onUpdateSpendingPeriod={setSpendingPeriod} />}
        </div>
      </main>

      {isLogoutModalOpen && (
          <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/95 backdrop-blur-2xl animate-fade-in">
              <div className="bg-[#0f172a] border border-rose-500/30 rounded-[3rem] w-full max-w-sm shadow-[0_0_100px_rgba(244,63,94,0.2)] p-10 text-center animate-slide-up relative">
                  <div className="w-20 h-20 bg-rose-500/20 rounded-[2rem] flex items-center justify-center mx-auto mb-8 border border-rose-500/30"><ShieldX className="w-10 h-10 text-rose-500" /></div>
                  <h3 className="text-2xl font-black text-white mb-3 uppercase tracking-tighter">Terminate?</h3>
                  <div className="space-y-4">
                      <button onClick={confirmLogout} className="w-full py-4 bg-rose-600 hover:bg-rose-500 text-white font-black rounded-2xl shadow-xl transition-all">Sign Out</button>
                      <button onClick={() => setIsLogoutModalOpen(false)} className="w-full py-4 bg-slate-900/50 text-slate-400 font-bold rounded-2xl border border-white/5 hover:text-white transition-all">Stay Connected</button>
                  </div>
              </div>
          </div>
      )}

      <ToastContainer toasts={toasts} onRemove={removeToast} />
    </div>
  );
};

export default App;

import React, { useMemo, useState } from 'react';
import { Account, UserPlan } from '../types';
import { TrendingUp, PieChart as PieChartIcon, DollarSign, Calculator, Building, Landmark, Percent, Heart, Briefcase } from 'lucide-react';
import { PieChart, Pie, Cell, Tooltip, ResponsiveContainer } from 'recharts';

interface InvestmentProps {
  accounts: Account[];
  formatCurrency: (amount: number) => string | React.ReactNode;
  userPlan: UserPlan;
}

const COLORS = ['#6366f1', '#ec4899', '#10b981', '#f59e0b', '#3b82f6', '#8b5cf6', '#06b6d4', '#f43f5e'];

const Investment: React.FC<InvestmentProps> = ({ accounts, formatCurrency, userPlan }) => {
  // Calculator State
  const [activeCalc, setActiveCalc] = useState<'compound' | 'ira' | 'insurance' | 'pension' | 'real_estate' | 'roi'>('compound');

  // Compound Input
  const [compP, setCompP] = useState(10000);
  const [compR, setCompR] = useState(7);
  const [compT, setCompT] = useState(10);
  const [compN, setCompN] = useState(12);

  // IRA Input
  const [iraPV, setIraPV] = useState(50000);
  const [iraC, setIraC] = useState(6000);
  const [iraR, setIraR] = useState(7);
  const [iraT, setIraT] = useState(20);

  // Insurance Input
  const [insIncome, setInsIncome] = useState(80000);
  const [insYears, setInsYears] = useState(10);
  const [insDebt, setInsDebt] = useState(150000);
  const [insHealth, setInsHealth] = useState<'excellent' | 'average' | 'poor'>('average');
  const [insTerm, setInsTerm] = useState(20);

  // Pension Input
  const [penP0, setPenP0] = useState(100000);
  const [penC, setPenC] = useState(12000);
  const [penR, setPenR] = useState(5);
  const [penN, setPenN] = useState(15);
  const [penDrawN, setPenDrawN] = useState(240); // 20 years in months
  const [penDrawI, setPenDrawI] = useState(4); // Drawdown interest rate

  // Real Estate Input
  const [reRent, setReRent] = useState(2000);
  const [rePrice, setRePrice] = useState(400000);

  // ROI Input
  const [roiInitial, setRoiInitial] = useState(10000);
  const [roiFinal, setRoiFinal] = useState(15000);
  const [roiCosts, setRoiCosts] = useState(500);

  const investmentAccounts = useMemo(() => {
    return accounts.filter(a => a.type === 'Investment');
  }, [accounts]);

  const totalPortfolioValue = useMemo(() => {
    return investmentAccounts.reduce((acc, curr) => acc + curr.balance, 0);
  }, [investmentAccounts]);

  const allocationData = useMemo(() => {
      if (investmentAccounts.length === 0) return [];
      return investmentAccounts.map(acc => ({
          name: acc.name,
          value: acc.balance
      })).sort((a, b) => b.value - a.value);
  }, [investmentAccounts]);

  // Logic Implementations
  const compoundResult = useMemo(() => {
      // A = P * (1 + r/n)^(n*t)
      const rDec = compR / 100;
      return compP * Math.pow((1 + rDec/compN), (compN * compT));
  }, [compP, compR, compN, compT]);

  const iraResult = useMemo(() => {
      // FV = PV * (1+r)^t + C * [((1+r)^t - 1) / r]
      const rDec = iraR / 100;
      const term1 = iraPV * Math.pow((1 + rDec), iraT);
      const term2 = iraC * ((Math.pow((1 + rDec), iraT) - 1) / rDec);
      return term1 + term2;
  }, [iraPV, iraR, iraC, iraT]);

  const insuranceResult = useMemo(() => {
      // Coverage = (Income * Years) + Debt
      const coverage = (insIncome * insYears) + insDebt;

      // Mock Premium Function f(Coverage, Term, Health)
      // Base: $0.5 per $1000 coverage/month
      let baseRate = (coverage / 1000) * 0.5;

      // Term Multiplier
      if (insTerm > 20) baseRate *= 1.5;
      else if (insTerm < 15) baseRate *= 0.8;

      // Health Multiplier
      if (insHealth === 'poor') baseRate *= 1.5;
      else if (insHealth === 'excellent') baseRate *= 0.8;

      return { coverage, premium: baseRate };
  }, [insIncome, insYears, insDebt, insHealth, insTerm]);

  const pensionResult = useMemo(() => {
      // Pot FV = P0(1+r)^n + C * [((1+r)^n - 1) / r]
      const rDec = penR / 100;
      const term1 = penP0 * Math.pow((1 + rDec), penN);
      const term2 = penC * ((Math.pow((1 + rDec), penN) - 1) / rDec);
      const fv = term1 + term2;

      // Drawdown Payment = FV * [ i / (1 - (1+i)^-N) ]
      const i = (penDrawI / 100) / 12;
      const payment = fv * (i / (1 - Math.pow((1 + i), -penDrawN)));

      return { fv, payment };
  }, [penP0, penC, penR, penN, penDrawN, penDrawI]);

  const realEstateResult = useMemo(() => {
      const annualRent = reRent * 12;
      const yieldVal = rePrice > 0 ? (annualRent / rePrice) * 100 : 0;
      return { annualRent, yieldVal };
  }, [reRent, rePrice]);

  const roiResult = useMemo(() => {
      const totalInv = roiInitial + roiCosts;
      const netProfit = roiFinal - totalInv;
      const roi = totalInv > 0 ? (netProfit / totalInv) * 100 : 0;
      return { netProfit, roi };
  }, [roiInitial, roiFinal, roiCosts]);

  return (
    <div className="space-y-8 animate-slide-up pb-20">
        <div className="flex justify-between items-end">
            <div>
                <h2 className="text-3xl font-black text-white tracking-tight flex items-center gap-3">
                    <TrendingUp className="w-8 h-8 text-emerald-400" />
                    Investment Node
                </h2>
                <p className="text-slate-400 mt-2 font-medium">Portfolio metrics and projection engines.</p>
            </div>
        </div>

        {/* Portfolio Overview Cards */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="glass-card p-6 rounded-[2rem] border border-white/5 bg-slate-900/40 flex items-center justify-between">
                <div>
                    <div className="flex items-center gap-3 mb-2">
                        <div className="p-2 rounded-xl bg-emerald-500/10"><DollarSign className="w-5 h-5 text-emerald-400" /></div>
                        <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Total Valuation</span>
                    </div>
                    <div className="text-3xl font-black text-white tracking-tighter">{formatCurrency(totalPortfolioValue)}</div>
                </div>
            </div>

            <div className="glass-card p-6 rounded-[2rem] border border-white/5 bg-slate-900/40 flex items-center justify-between">
                <div>
                    <div className="flex items-center gap-3 mb-2">
                        <div className="p-2 rounded-xl bg-indigo-500/10"><PieChartIcon className="w-5 h-5 text-indigo-400" /></div>
                        <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Active Positions</span>
                    </div>
                    <div className="text-3xl font-black text-white tracking-tighter">{investmentAccounts.length}</div>
                </div>
            </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
            {/* Allocation Donut */}
            <div className="glass-card p-8 rounded-[2.5rem] border border-white/10 flex flex-col h-[400px]">
                <h3 className="text-lg font-bold text-white flex items-center gap-2 mb-6">
                    <PieChartIcon className="w-5 h-5 text-purple-400" /> Allocation
                </h3>

                <div className="flex-1 min-h-0 relative">
                    {allocationData.length > 0 ? (
                        <ResponsiveContainer width="100%" height="100%">
                            <PieChart>
                                <Pie
                                    data={allocationData}
                                    cx="50%"
                                    cy="50%"
                                    innerRadius={70}
                                    outerRadius={100}
                                    paddingAngle={5}
                                    dataKey="value"
                                >
                                    {allocationData.map((entry, index) => (
                                        <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                    ))}
                                </Pie>
                                <Tooltip 
                                    contentStyle={{ backgroundColor: '#020617', border: '1px solid rgba(255,255,255,0.1)', borderRadius: '12px' }}
                                    itemStyle={{ color: '#fff', fontSize: '12px', fontWeight: 'bold' }}
                                    formatter={(val: number) => formatCurrency(val)}
                                />
                            </PieChart>
                        </ResponsiveContainer>
                    ) : (
                        <div className="absolute inset-0 flex flex-col items-center justify-center text-center opacity-50">
                            <div className="w-16 h-16 rounded-full bg-slate-800 flex items-center justify-center mb-3">
                                <PieChartIcon className="w-8 h-8 text-slate-500" />
                            </div>
                            <p className="text-xs font-bold text-slate-500 uppercase">No Investment Accounts</p>
                        </div>
                    )}
                </div>
            </div>

            {/* Assets List */}
            <div className="glass-card p-8 rounded-[2.5rem] border border-white/10 h-[400px] flex flex-col">
                <h3 className="text-lg font-bold text-white mb-6">Holdings</h3>
                <div className="overflow-y-auto custom-scrollbar flex-1 pr-2">
                    <table className="w-full text-left">
                        <thead className="text-[10px] font-black text-slate-500 uppercase tracking-widest border-b border-white/5 sticky top-0 bg-[#0f172a] z-10">
                            <tr>
                                <th className="pb-4 pl-2">Asset</th>
                                <th className="pb-4 text-right">Balance</th>
                                <th className="pb-4 text-right pr-2">Share</th>
                            </tr>
                        </thead>
                        <tbody className="text-sm">
                            {investmentAccounts.length > 0 ? (
                                investmentAccounts.map((acc, i) => (
                                    <tr key={acc.id} className="group border-b border-white/5 last:border-0 hover:bg-white/5 transition-colors">
                                        <td className="py-4 pl-2 font-bold text-white">
                                            <div className="flex items-center gap-3">
                                                <div className="w-2.5 h-2.5 rounded-full shrink-0" style={{ backgroundColor: COLORS[i % COLORS.length] }}></div>
                                                <div className="min-w-0">
                                                    <div className="truncate max-w-[120px]">{acc.name}</div>
                                                    <div className="text-[10px] text-slate-500 font-medium uppercase tracking-wider truncate max-w-[120px]">{acc.institution}</div>
                                                </div>
                                            </div>
                                        </td>
                                        <td className="py-4 text-right font-bold text-white">{formatCurrency(acc.balance)}</td>
                                        <td className="py-4 text-right pr-2 text-slate-400 font-medium">
                                            {totalPortfolioValue > 0 ? ((acc.balance / totalPortfolioValue) * 100).toFixed(1) : 0}%
                                        </td>
                                    </tr>
                                ))
                            ) : (
                                <tr>
                                    <td colSpan={3} className="py-8 text-center text-slate-500 font-medium text-xs">
                                        No investment accounts found.
                                    </td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>

        {/* Financial Logic Core (Calculators) */}
        <div className="glass-card p-8 rounded-[2.5rem] border border-white/10 bg-slate-900/20">
            <div className="flex items-center gap-3 mb-8">
                <div className="p-3 bg-indigo-600/20 rounded-xl text-indigo-400"><Calculator className="w-6 h-6" /></div>
                <div>
                    <h3 className="text-xl font-black text-white tracking-tight">Financial Logic Core</h3>
                    <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1">Projection Engines</p>
                </div>
            </div>

            <div className="flex gap-2 overflow-x-auto custom-scrollbar pb-4 mb-6">
                {[
                    { id: 'compound', label: 'Compound Interest', icon: <TrendingUp className="w-4 h-4" /> },
                    { id: 'ira', label: 'IRA Projector', icon: <Landmark className="w-4 h-4" /> },
                    { id: 'insurance', label: 'Life Insurance', icon: <Heart className="w-4 h-4" /> },
                    { id: 'pension', label: 'Pension Pot', icon: <Briefcase className="w-4 h-4" /> },
                    { id: 'real_estate', label: 'Real Estate Yield', icon: <Building className="w-4 h-4" /> },
                    { id: 'roi', label: 'ROI Calculator', icon: <Percent className="w-4 h-4" /> }
                ].map((item) => (
                    <button 
                        key={item.id}
                        onClick={() => setActiveCalc(item.id as any)}
                        className={`flex items-center gap-2 px-4 py-3 rounded-xl text-xs font-bold whitespace-nowrap transition-all ${activeCalc === item.id ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'bg-slate-800 text-slate-400 hover:text-white hover:bg-slate-700'}`}
                    >
                        {item.icon} {item.label}
                    </button>
                ))}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 animate-fade-in">
                {/* Inputs Column */}
                <div className="space-y-5">
                    {activeCalc === 'compound' && (
                        <>
                            <InputGroup label="Principal (P)" value={compP} onChange={setCompP} prefix="$" />
                            <InputGroup label="Annual Rate (r)" value={compR} onChange={setCompR} suffix="%" />
                            <InputGroup label="Years (t)" value={compT} onChange={setCompT} suffix="yrs" />
                            <InputGroup label="Compounds / Year (n)" value={compN} onChange={setCompN} />
                        </>
                    )}
                    {activeCalc === 'ira' && (
                        <>
                            <InputGroup label="Current Savings (PV)" value={iraPV} onChange={setIraPV} prefix="$" />
                            <InputGroup label="Annual Contribution (C)" value={iraC} onChange={setIraC} prefix="$" />
                            <InputGroup label="Annual Return (r)" value={iraR} onChange={setIraR} suffix="%" />
                            <InputGroup label="Years to Retire (t)" value={iraT} onChange={setIraT} suffix="yrs" />
                        </>
                    )}
                    {activeCalc === 'insurance' && (
                        <>
                            <InputGroup label="Annual Income" value={insIncome} onChange={setInsIncome} prefix="$" />
                            <InputGroup label="Years Replacement" value={insYears} onChange={setInsYears} suffix="yrs" />
                            <InputGroup label="Total Debt" value={insDebt} onChange={setInsDebt} prefix="$" />
                            <InputGroup label="Policy Term" value={insTerm} onChange={setInsTerm} suffix="yrs" />
                            <div>
                                <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-1.5 block">Health Category</label>
                                <select value={insHealth} onChange={e => setInsHealth(e.target.value as any)} className="w-full bg-slate-950 border border-white/10 rounded-xl px-4 py-3 text-white text-sm focus:border-indigo-500 outline-none">
                                    <option value="excellent">Excellent</option>
                                    <option value="average">Average</option>
                                    <option value="poor">Poor</option>
                                </select>
                            </div>
                        </>
                    )}
                    {activeCalc === 'pension' && (
                        <>
                            <InputGroup label="Current Pot (P0)" value={penP0} onChange={setPenP0} prefix="$" />
                            <InputGroup label="Annual Contrib (C)" value={penC} onChange={setPenC} prefix="$" />
                            <InputGroup label="Growth Rate (r)" value={penR} onChange={setPenR} suffix="%" />
                            <InputGroup label="Years to Retire (n)" value={penN} onChange={setPenN} suffix="yrs" />
                            <div className="pt-4 border-t border-white/5">
                                <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-3">Drawdown Settings</p>
                                <div className="grid grid-cols-2 gap-4">
                                    <InputGroup label="Months (N)" value={penDrawN} onChange={setPenDrawN} />
                                    <InputGroup label="Post-Retire Rate (i)" value={penDrawI} onChange={setPenDrawI} suffix="%" />
                                </div>
                            </div>
                        </>
                    )}
                    {activeCalc === 'real_estate' && (
                        <>
                            <InputGroup label="Monthly Rent" value={reRent} onChange={setReRent} prefix="$" />
                            <InputGroup label="Property Price" value={rePrice} onChange={setRePrice} prefix="$" />
                        </>
                    )}
                    {activeCalc === 'roi' && (
                        <>
                            <InputGroup label="Initial Investment" value={roiInitial} onChange={setRoiInitial} prefix="$" />
                            <InputGroup label="Final Value" value={roiFinal} onChange={setRoiFinal} prefix="$" />
                            <InputGroup label="Total Costs" value={roiCosts} onChange={setRoiCosts} prefix="$" />
                        </>
                    )}
                </div>

                {/* Results Column */}
                <div className="bg-slate-950/50 rounded-[2rem] border border-white/5 p-8 flex flex-col justify-center items-center text-center relative overflow-hidden">
                    <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-500/5 rounded-full blur-[80px]"></div>

                    {activeCalc === 'compound' && (
                        <>
                            <div className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] mb-2">Future Value (A)</div>
                            <div className="text-4xl font-black text-white tracking-tighter mb-4">{formatCurrency(compoundResult)}</div>
                            <p className="text-xs text-slate-400 font-medium max-w-xs">Projected total after {compT} years compounding {compN} times/year.</p>
                        </>
                    )}

                    {activeCalc === 'ira' && (
                        <>
                            <div className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] mb-2">Retirement Value (FV)</div>
                            <div className="text-4xl font-black text-emerald-400 tracking-tighter mb-4">{formatCurrency(iraResult)}</div>
                            <p className="text-xs text-slate-400 font-medium max-w-xs">Total accumulation at retirement based on annuity due growth.</p>
                        </>
                    )}

                    {activeCalc === 'insurance' && (
                        <>
                            <div className="mb-6 w-full">
                                <div className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] mb-1">Recommended Coverage</div>
                                <div className="text-3xl font-black text-white">{formatCurrency(insuranceResult.coverage)}</div>
                            </div>
                            <div className="w-full pt-6 border-t border-white/5">
                                <div className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] mb-1">Est. Monthly Premium</div>
                                <div className="text-2xl font-black text-indigo-400">~{formatCurrency(insuranceResult.premium)}/mo</div>
                                <p className="text-[9px] text-slate-500 mt-2 italic">Estimate only. Based on term & health factor.</p>
                            </div>
                        </>
                    )}

                    {activeCalc === 'pension' && (
                        <>
                            <div className="mb-6 w-full">
                                <div className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] mb-1">Projected Pot</div>
                                <div className="text-3xl font-black text-white">{formatCurrency(pensionResult.fv)}</div>
                            </div>
                            <div className="w-full pt-6 border-t border-white/5">
                                <div className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] mb-1">Est. Monthly Drawdown</div>
                                <div className="text-2xl font-black text-emerald-400">{formatCurrency(pensionResult.payment)}/mo</div>
                                <p className="text-[9px] text-slate-500 mt-2 italic">For {Math.floor(penDrawN/12)} years post-retirement.</p>
                            </div>
                        </>
                    )}

                    {activeCalc === 'real_estate' && (
                        <>
                            <div className="mb-6 w-full">
                                <div className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] mb-1">Annual Income</div>
                                <div className="text-3xl font-black text-white">{formatCurrency(realEstateResult.annualRent)}</div>
                            </div>
                            <div className="w-full pt-6 border-t border-white/5">
                                <div className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] mb-1">Gross Rental Yield</div>
                                <div className={`text-4xl font-black ${realEstateResult.yieldVal > 5 ? 'text-emerald-400' : 'text-amber-400'}`}>
                                    {realEstateResult.yieldVal.toFixed(2)}%
                                </div>
                            </div>
                        </>
                    )}

                    {activeCalc === 'roi' && (
                        <>
                            <div className="mb-6 w-full">
                                <div className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] mb-1">Net Profit/Loss</div>
                                <div className={`text-3xl font-black ${roiResult.netProfit >= 0 ? 'text-white' : 'text-rose-400'}`}>{formatCurrency(roiResult.netProfit)}</div>
                            </div>
                            <div className="w-full pt-6 border-t border-white/5">
                                <div className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] mb-1">ROI Percentage</div>
                                <div className={`text-4xl font-black ${roiResult.roi >= 0 ? 'text-emerald-400' : 'text-rose-500'}`}>
                                    {roiResult.roi.toFixed(2)}%
                                </div>
                                <p className="text-[9px] text-slate-500 mt-2 font-bold uppercase">{roiResult.roi >= 0 ? 'Profitable' : 'Loss'}</p>
                            </div>
                        </>
                    )}
                </div>
            </div>
        </div>
    </div>
  );
};

const InputGroup: React.FC<{ label: string, value: number, onChange: (v: number) => void, prefix?: string, suffix?: string }> = ({ label, value, onChange, prefix, suffix }) => (
    <div>
        <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-1.5 block">{label}</label>
        <div className="relative">
            {prefix && <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500 font-bold">{prefix}</span>}
            <input 
                type="number" 
                value={value} 
                onChange={(e) => onChange(parseFloat(e.target.value))} 
                className={`w-full bg-slate-950 border border-white/10 rounded-xl py-3 text-white text-sm focus:border-indigo-500 outline-none font-medium ${prefix ? 'pl-8' : 'pl-4'} ${suffix ? 'pr-10' : 'pr-4'}`}
            />
            {suffix && <span className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-500 font-bold text-xs">{suffix}</span>}
        </div>
    </div>
);

export default Investment;

payload.text:
This is a fantastic strategic move. Moving from local storage to **Firebase** will transform Nova from a temporary browser demo into a permanent, multi-device SaaS product.

"Firebase Studio" (usually referred to as the **Firebase Console**) provides the Backend-as-a-Service (BaaS) infrastructure you need.

Here is the architectural roadmap to migrate your React application to a full-stack Firebase app.

### Phase 1: The Setup (Firebase Console)

1.  **Create Project:** Go to [console.firebase.google.com](https://console.firebase.google.com/) and create a new project (e.g., "nova-finance-ai").
2.  **Enable Authentication:**
    *   Go to **Build > Authentication**.
    *   Click "Get Started".
    *   Enable **Google** and **Email/Password** providers.
3.  **Enable Firestore Database:**
    *   Go to **Build > Firestore Database**.
    *   Click "Create Database".
    *   Start in **Test Mode** (we will secure this later).
    *   Choose a location close to you.

### Phase 2: Connect Code to Cloud

Install the Firebase SDK in your project terminal:

```bash
npm install firebase
```

Create a new file `src/firebase.ts` to initialize the connection. You get these keys from Project Settings > General > Your Apps > Web App in the Firebase Console.

```typescript
// src/firebase.ts
import { initializeApp } from "firebase/app";
import { getAuth, GoogleAuthProvider } from "firebase/auth";
import { getFirestore } from "firebase/firestore";

const firebaseConfig = {
  apiKey: "YOUR_API_KEY_FROM_CONSOLE",
  authDomain: "nova-finance.firebaseapp.com",
  projectId: "nova-finance",
  storageBucket: "nova-finance.appspot.com",
  messagingSenderId: "...",
  appId: "..."
};

const app = initializeApp(firebaseConfig);
export const auth = getAuth(app);
export const googleProvider = new GoogleAuthProvider();
export const db = getFirestore(app);
```

### Phase 3: Migrate Authentication

In your `App.tsx` and `AuthPage.tsx`, you currently use `localStorage`. You need to replace that with Firebase Auth listeners.

**In `App.tsx`:**

```typescript
import { onAuthStateChanged, User } from "firebase/auth";
import { auth } from './firebase';

const App: React.FC = () => {
  const [user, setUser] = useState<User | null>(null);

  useEffect(() => {
    // This listener automatically detects login/logout state across reloads
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
      if (currentUser) {
        // Trigger data fetching here
        fetchUserData(currentUser.uid); 
      }
    });
    return () => unsubscribe();
  }, []);

  // ... rest of your code
```

**In `AuthPage.tsx`:**

```typescript
import { signInWithPopup, signInWithEmailAndPassword, createUserWithEmailAndPassword } from "firebase/auth";
import { auth, googleProvider } from '../firebase';

// Inside your component
const handleGoogleLogin = async () => {
  try {
    await signInWithPopup(auth, googleProvider);
    // onLoginSuccess is handled by the useEffect in App.tsx
  } catch (error) {
    console.error("Login failed", error);
  }
};
```

### Phase 4: Migrate Data (The Hard Part)

Local Storage is synchronous. Firebase is asynchronous. You need to rewrite your data handling hooks.

**Data Structure Strategy:**
Instead of one big JSON blob, use Firestore Collections.
Structure: `users/{userId}/transactions/{transactionId}`

**Create a Data Service (`services/firebaseService.ts`):**

```typescript
import { db } from '../firebase';
import { collection, addDoc, query, where, getDocs, doc, deleteDoc, updateDoc } from "firebase/firestore";
import { Transaction } from '../types';

// FETCH TRANSACTIONS
export const getTransactions = async (userId: string) => {
  const q = query(collection(db, "transactions"), where("userId", "==", userId));
  const querySnapshot = await getDocs(q);
  return querySnapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Transaction));
};

// ADD TRANSACTION
export const addTransaction = async (userId: string, transaction: Omit<Transaction, 'id'>) => {
  const docRef = await addDoc(collection(db, "transactions"), {
    ...transaction,
    userId, // Important: Link data to specific user
    createdAt: new Date()
  });
  return { id: docRef.id, ...transaction };
};

// DELETE TRANSACTION
export const deleteTransaction = async (id: string) => {
  await deleteDoc(doc(db, "transactions", id));
};
```

You will need to repeat this pattern for `Accounts`, `Goals`, and `Budgets`.

### Phase 5: Hosting & Deployment

To make your app live on the internet:

1.  Install Firebase CLI tools:
    ```bash
    npm install -g firebase-tools
    ```
2.  Login:
    ```bash
    firebase login
    ```
3.  Initialize project:
    ```bash
    firebase init
    ```
    *   Select **Hosting**.
    *   Select your project.
    *   Type `dist` (or `build`) as your public directory.
    *   Configure as a single-page app? **Yes**.
    *   Automatic builds with GitHub? (Optional).
4.  Build and Deploy:
    ```bash
    npm run build
    firebase deploy
    ```

### Phase 6: Advanced Gemini Integration (Cloud Functions)

Currently, your API Key is exposed in the frontend code (`process.env.API_KEY`). In a real production app, this is a security risk.

To fix this with Firebase:
1.  Enable **Cloud Functions** in Firebase Console.
2.  Move your `geminiService.ts` logic to a Cloud Function.
3.  Your frontend calls the Cloud Function, and the Cloud Function calls Gemini (keeping the key secret on the server).

### Summary Checklist for Migration

1.  [ ] Replace `localStorage` calls with `useState` and `useEffect`.
2.  [ ] Replace mock Auth with `firebase/auth`.
3.  [ ] Replace mock Data arrays with `firebase/firestore` calls.
4.  [ ] Add a loading state (spinner) to `App.tsx` because fetching data from the cloud takes a few milliseconds, unlike local storage.
5.  [ ] Deploy via Firebase Hosting.

