import React, { useMemo, useState } from 'react';
import { Account, UserPlan } from '../types';
import { TrendingUp, PieChart as PieChartIcon, DollarSign, Calculator, Building, Landmark, Percent, Heart, Briefcase } from 'lucide-react';
import { PieChart, Pie, Cell, Tooltip, ResponsiveContainer } from 'recharts';

interface InvestmentProps {
  accounts: Account[];
  formatCurrency: (amount: number) => string | React.ReactNode;
  userPlan: UserPlan;
}

const COLORS = ['#6366f1', '#ec4899', '#10b981', '#f59e0b', '#3b82f6', '#8b5cf6', '#06b6d4', '#f43f5e'];

const Investment: React.FC<InvestmentProps> = ({ accounts, formatCurrency, userPlan }) => {
  // Calculator State
  const [activeCalc, setActiveCalc] = useState<'compound' | 'ira' | 'insurance' | 'pension' | 'real_estate' | 'roi'>('compound');

  // Compound Input - Reset to 0
  const [compP, setCompP] = useState(0);
  const [compR, setCompR] = useState(0);
  const [compT, setCompT] = useState(0);
  const [compN, setCompN] = useState(12); // Frequency defaults to 12 (monthly) as it's a configuration, not user data

  // IRA Input - Reset to 0
  const [iraPV, setIraPV] = useState(0);
  const [iraC, setIraC] = useState(0);
  const [iraR, setIraR] = useState(0);
  const [iraT, setIraT] = useState(0);

  // Insurance Input - Reset to 0
  const [insIncome, setInsIncome] = useState(0);
  const [insYears, setInsYears] = useState(0);
  const [insDebt, setInsDebt] = useState(0);
  const [insHealth, setInsHealth] = useState<'excellent' | 'average' | 'poor'>('average');
  const [insTerm, setInsTerm] = useState(0);

  // Pension Input - Reset to 0
  const [penP0, setPenP0] = useState(0);
  const [penC, setPenC] = useState(0);
  const [penR, setPenR] = useState(0);
  const [penN, setPenN] = useState(0);
  const [penDrawN, setPenDrawN] = useState(0); 
  const [penDrawI, setPenDrawI] = useState(0); 

  // Real Estate Input - Reset to 0
  const [reRent, setReRent] = useState(0);
  const [rePrice, setRePrice] = useState(0);

  // ROI Input - Reset to 0
  const [roiInitial, setRoiInitial] = useState(0);
  const [roiFinal, setRoiFinal] = useState(0);
  const [roiCosts, setRoiCosts] = useState(0);

  const investmentAccounts = useMemo(() => {
    return accounts.filter(a => a.type === 'Investment');
  }, [accounts]);

  const totalPortfolioValue = useMemo(() => {
    return investmentAccounts.reduce((acc, curr) => acc + curr.balance, 0);
  }, [investmentAccounts]);

  const allocationData = useMemo(() => {
      if (investmentAccounts.length === 0) return [];
      return investmentAccounts.map(acc => ({
          name: acc.name,
          value: acc.balance
      })).sort((a, b) => b.value - a.value);
  }, [investmentAccounts]);

  // Logic Implementations
  const compoundResult = useMemo(() => {
      if (compP === 0) return 0;
      // A = P * (1 + r/n)^(n*t)
      const rDec = compR / 100;
      return compP * Math.pow((1 + rDec/compN), (compN * compT));
  }, [compP, compR, compN, compT]);

  const iraResult = useMemo(() => {
      if (iraPV === 0 && iraC === 0) return 0;
      // FV = PV * (1+r)^t + C * [((1+r)^t - 1) / r]
      const rDec = iraR / 100;
      const term1 = iraPV * Math.pow((1 + rDec), iraT);
      const term2 = rDec > 0 ? iraC * ((Math.pow((1 + rDec), iraT) - 1) / rDec) : iraC * iraT;
      return term1 + term2;
  }, [iraPV, iraR, iraC, iraT]);

  const insuranceResult = useMemo(() => {
      // Coverage = (Income * Years) + Debt
      const coverage = (insIncome * insYears) + insDebt;

      // Mock Premium Function f(Coverage, Term, Health)
      // Base: $0.5 per $1000 coverage/month
      let baseRate = (coverage / 1000) * 0.5;

      // Term Multiplier
      if (insTerm > 20) baseRate *= 1.5;
      else if (insTerm < 15) baseRate *= 0.8;

      // Health Multiplier
      if (insHealth === 'poor') baseRate *= 1.5;
      else if (insHealth === 'excellent') baseRate *= 0.8;

      return { coverage, premium: baseRate };
  }, [insIncome, insYears, insDebt, insHealth, insTerm]);

  const pensionResult = useMemo(() => {
      // Pot FV = P0(1+r)^n + C * [((1+r)^n - 1) / r]
      const rDec = penR / 100;
      const term1 = penP0 * Math.pow((1 + rDec), penN);
      const term2 = rDec > 0 ? penC * ((Math.pow((1 + rDec), penN) - 1) / rDec) : penC * penN;
      const fv = term1 + term2;

      // Drawdown Payment = FV * [ i / (1 - (1+i)^-N) ]
      const i = (penDrawI / 100) / 12;
      const payment = i > 0 && penDrawN > 0 ? fv * (i / (1 - Math.pow((1 + i), -penDrawN))) : (penDrawN > 0 ? fv / penDrawN : 0);

      return { fv, payment };
  }, [penP0, penC, penR, penN, penDrawN, penDrawI]);

  const realEstateResult = useMemo(() => {
      const annualRent = reRent * 12;
      const yieldVal = rePrice > 0 ? (annualRent / rePrice) * 100 : 0;
      return { annualRent, yieldVal };
  }, [reRent, rePrice]);

  const roiResult = useMemo(() => {
      const totalInv = roiInitial + roiCosts;
      const netProfit = roiFinal - totalInv;
      const roi = totalInv > 0 ? (netProfit / totalInv) * 100 : 0;
      return { netProfit, roi };
  }, [roiInitial, roiFinal, roiCosts]);

  return (
    <div className="space-y-8 animate-slide-up pb-20">
        <div className="flex justify-between items-end">
            <div>
                <h2 className="text-3xl font-black text-white tracking-tight flex items-center gap-3">
                    <TrendingUp className="w-8 h-8 text-emerald-400" />
                    Investment Node
                </h2>
                <p className="text-slate-400 mt-2 font-medium">Portfolio metrics and projection engines.</p>
            </div>
        </div>

        {/* Portfolio Overview Cards */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="glass-card p-6 rounded-[2rem] border border-white/5 bg-slate-900/40 flex items-center justify-between">
                <div>
                    <div className="flex items-center gap-3 mb-2">
                        <div className="p-2 rounded-xl bg-emerald-500/10"><DollarSign className="w-5 h-5 text-emerald-400" /></div>
                        <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Total Valuation</span>
                    </div>
                    <div className="text-3xl font-black text-white tracking-tighter">{formatCurrency(totalPortfolioValue)}</div>
                </div>
            </div>

            <div className="glass-card p-6 rounded-[2rem] border border-white/5 bg-slate-900/40 flex items-center justify-between">
                <div>
                    <div className="flex items-center gap-3 mb-2">
                        <div className="p-2 rounded-xl bg-indigo-500/10"><PieChartIcon className="w-5 h-5 text-indigo-400" /></div>
                        <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Active Positions</span>
                    </div>
                    <div className="text-3xl font-black text-white tracking-tighter">{investmentAccounts.length}</div>
                </div>
            </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
            {/* Allocation Donut */}
            <div className="glass-card p-8 rounded-[2.5rem] border border-white/10 flex flex-col h-[400px]">
                <h3 className="text-lg font-bold text-white flex items-center gap-2 mb-6">
                    <PieChartIcon className="w-5 h-5 text-purple-400" /> Allocation
                </h3>

                <div className="flex-1 min-h-0 relative">
                    {allocationData.length > 0 ? (
                        <ResponsiveContainer width="100%" height="100%">
                            <PieChart>
                                <Pie
                                    data={allocationData}
                                    cx="50%"
                                    cy="50%"
                                    innerRadius={70}
                                    outerRadius={100}
                                    paddingAngle={5}
                                    dataKey="value"
                                >
                                    {allocationData.map((entry, index) => (
                                        <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                    ))}
                                </Pie>
                                <Tooltip 
                                    contentStyle={{ backgroundColor: '#020617', border: '1px solid rgba(255,255,255,0.1)', borderRadius: '12px' }}
                                    itemStyle={{ color: '#fff', fontSize: '12px', fontWeight: 'bold' }}
                                    formatter={(val: number) => formatCurrency(val)}
                                />
                            </PieChart>
                        </ResponsiveContainer>
                    ) : (
                        <div className="absolute inset-0 flex flex-col items-center justify-center text-center opacity-50">
                            <div className="w-16 h-16 rounded-full bg-slate-800 flex items-center justify-center mb-3">
                                <PieChartIcon className="w-8 h-8 text-slate-500" />
                            </div>
                            <p className="text-xs font-bold text-slate-500 uppercase">No Investment Accounts</p>
                        </div>
                    )}
                </div>
            </div>

            {/* Assets List */}
            <div className="glass-card p-8 rounded-[2.5rem] border border-white/10 h-[400px] flex flex-col">
                <h3 className="text-lg font-bold text-white mb-6">Holdings</h3>
                <div className="overflow-y-auto custom-scrollbar flex-1 pr-2">
                    <table className="w-full text-left">
                        <thead className="text-[10px] font-black text-slate-500 uppercase tracking-widest border-b border-white/5 sticky top-0 bg-[#0f172a] z-10">
                            <tr>
                                <th className="pb-4 pl-2">Asset</th>
                                <th className="pb-4 text-right">Balance</th>
                                <th className="pb-4 text-right pr-2">Share</th>
                            </tr>
                        </thead>
                        <tbody className="text-sm">
                            {investmentAccounts.length > 0 ? (
                                investmentAccounts.map((acc, i) => (
                                    <tr key={acc.id} className="group border-b border-white/5 last:border-0 hover:bg-white/5 transition-colors">
                                        <td className="py-4 pl-2 font-bold text-white">
                                            <div className="flex items-center gap-3">
                                                <div className="w-2.5 h-2.5 rounded-full shrink-0" style={{ backgroundColor: COLORS[i % COLORS.length] }}></div>
                                                <div className="min-w-0">
                                                    <div className="truncate max-w-[120px]">{acc.name}</div>
                                                    <div className="text-[10px] text-slate-500 font-medium uppercase tracking-wider truncate max-w-[120px]">{acc.institution}</div>
                                                </div>
                                            </div>
                                        </td>
                                        <td className="py-4 text-right font-bold text-white">{formatCurrency(acc.balance)}</td>
                                        <td className="py-4 text-right pr-2 text-slate-400 font-medium">
                                            {totalPortfolioValue > 0 ? ((acc.balance / totalPortfolioValue) * 100).toFixed(1) : 0}%
                                        </td>
                                    </tr>
                                ))
                            ) : (
                                <tr>
                                    <td colSpan={3} className="py-8 text-center text-slate-500 font-medium text-xs">
                                        No investment accounts found.
                                    </td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>

        {/* Financial Logic Core (Calculators) */}
        <div className="glass-card p-8 rounded-[2.5rem] border border-white/10 bg-slate-900/20">
            <div className="flex items-center gap-3 mb-8">
                <div className="p-3 bg-indigo-600/20 rounded-xl text-indigo-400"><Calculator className="w-6 h-6" /></div>
                <div>
                    <h3 className="text-xl font-black text-white tracking-tight">Financial Logic Core</h3>
                    <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1">Projection Engines</p>
                </div>
            </div>

            <div className="flex gap-2 overflow-x-auto custom-scrollbar pb-4 mb-6">
                {[
                    { id: 'compound', label: 'Compound Interest', icon: <TrendingUp className="w-4 h-4" /> },
                    { id: 'ira', label: 'IRA Projector', icon: <Landmark className="w-4 h-4" /> },
                    { id: 'insurance', label: 'Life Insurance', icon: <Heart className="w-4 h-4" /> },
                    { id: 'pension', label: 'Pension Pot', icon: <Briefcase className="w-4 h-4" /> },
                    { id: 'real_estate', label: 'Real Estate Yield', icon: <Building className="w-4 h-4" /> },
