                    )}

                    {activeCalc === 'roi' && (
                        <>
                            <div className="mb-6 w-full">
                                <div className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] mb-1">Net Profit/Loss</div>
                                <div className={`text-3xl font-black ${roiResult.netProfit >= 0 ? 'text-white' : 'text-rose-400'}`}>{formatCurrency(roiResult.netProfit)}</div>
                            </div>
                            <div className="w-full pt-6 border-t border-white/5">
                                <div className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] mb-1">ROI Percentage</div>
                                <div className={`text-4xl font-black ${roiResult.roi >= 0 ? 'text-emerald-400' : 'text-rose-500'}`}>
                                    {roiResult.roi.toFixed(2)}%
                                </div>
                                <p className="text-[9px] text-slate-500 mt-2 font-bold uppercase">{roiResult.roi >= 0 ? 'Profitable' : 'Loss'}</p>
                            </div>
                        </>
                    )}
                </div>
            </div>
        </div>
    </div>
  );
};

const InputGroup: React.FC<{ label: string, value: number, onChange: (v: number) => void, prefix?: string, suffix?: string }> = ({ label, value, onChange, prefix, suffix }) => (
    <div>
        <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-1.5 block">{label}</label>
        <div className="relative">
            {prefix && <span className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500 font-bold">{prefix}</span>}
            <input 
                type="number" 
                value={value} 
                onChange={(e) => onChange(parseFloat(e.target.value))} 
                className={`w-full bg-slate-950 border border-white/10 rounded-xl py-3 text-white text-sm focus:border-indigo-500 outline-none font-medium ${prefix ? 'pl-8' : 'pl-4'} ${suffix ? 'pr-10' : 'pr-4'}`}
            />
            {suffix && <span className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-500 font-bold text-xs">{suffix}</span>}
        </div>
    </div>
);

export default Investment;

import React, { useState, useEffect, useRef } from 'react';
import { User, Mail, Save, Download, Trash2, Camera, RefreshCw, ZoomIn, FileJson, UserCircle, Upload, Move, Sparkles, Lock, AlertTriangle, XCircle, Image as ImageIcon, Heart, Terminal, Crown, CreditCard, Zap, Target } from 'lucide-react';
import { UserPlan, Language, Currency, ToastMessage, BotMode, SpendingPeriod } from '../types';

interface SettingsProps {
