                        <button className="w-full p-5 bg-slate-900/50 border border-white/5 rounded-2xl hover:bg-slate-800 hover:border-white/20 transition-all text-left group flex items-center justify-between">
                            <div>
                                <h4 className="font-bold text-white text-sm mb-1">Restore Protocol</h4>
                                <p className="text-xs text-slate-500 font-medium">Import external backup capsule.</p>
                            </div>
                            <FileJson className="w-5 h-5 text-slate-500 group-hover:text-emerald-400 transition-colors" />
                        </button>
                    </div>
                </div>

                <div className="mt-6 pt-6 border-t border-white/5">
                     <button 
                        onClick={() => setShowConfirmModal('reset')}
                        className="w-full p-5 bg-rose-950/10 border border-rose-500/10 rounded-2xl hover:bg-rose-950/20 hover:border-rose-500/30 transition-all text-left group flex items-center justify-between"
                    >
                        <div>
                            <h4 className="font-bold text-rose-400 text-sm mb-1">Nuclear Reset</h4>
                            <p className="text-xs text-rose-500/60 font-medium">Wipe all nodes and financial identity.</p>
                        </div>
                        <Trash2 className="w-5 h-5 text-rose-500/50 group-hover:text-rose-400 transition-colors" />
                    </button>
                </div>
            </div>
        </div>
      </div>

      {/* Confirmation Modal for Reset/Downgrade */}
      {showConfirmModal && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/90 backdrop-blur-xl animate-fade-in">
             <div className="relative max-w-sm w-full bg-slate-950 rounded-[2rem] border border-white/10 shadow-[0_0_100px_rgba(244,63,94,0.3)] overflow-hidden animate-slide-up ring-1 ring-white/5">
                 <div className="p-8 text-center">
                     <div className="w-16 h-16 rounded-full bg-rose-500/20 flex items-center justify-center mx-auto mb-6 ring-1 ring-rose-500/50 animate-pulse">
                        <AlertTriangle className="w-8 h-8 text-rose-500" />
                     </div>
                     <h3 className="text-2xl font-black text-white mb-2 uppercase tracking-tight">Security Check</h3>
                     <p className="text-rose-200 text-sm mb-6 leading-relaxed font-medium">
                         {showConfirmModal === 'reset' ? 'This will permanently purge all financial data.' : 'Downgrading removes access to premium AI features immediately.'}
                     </p>

                     <div className="mb-6 text-left">
                         <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest ml-1">
                             {localStorage.getItem('nova_vault_key') ? "Confirm Passcode" : "Authorization Required"}
                         </label>
                         <input 
                            type="password" 
                            autoFocus
                            value={confirmPassword}
                            onChange={(e) => { setConfirmPassword(e.target.value); setPasswordError(''); }}
                            onKeyDown={(e) => handleConfirmKeyDown(e, () => {
                                if (showConfirmModal === 'reset') onClearData();
                                if (showConfirmModal === 'downgrade' && onDowngrade) onDowngrade();
                            })}
                            placeholder={localStorage.getItem('nova_vault_key') ? "Enter vault password" : "Type 'CONFIRM'"}
                            className="w-full bg-slate-900 border border-white/10 rounded-xl p-3 text-white mt-1 focus:border-rose-500 focus:outline-none"
                         />
                         {passwordError && <p className="text-rose-500 text-xs mt-2 font-bold">{passwordError}</p>}
                         {!localStorage.getItem('nova_vault_key') && (
                             <p className="text-slate-500 text-[10px] mt-2 italic">Social Login? Type 'CONFIRM' to proceed.</p>
                         )}
                     </div>

                     <div className="grid grid-cols-2 gap-3">
                        <button 
                            onClick={() => {
                                setShowConfirmModal(null);
                                setConfirmPassword('');
                                setPasswordError('');
                            }} 
                            className="py-3 bg-slate-800 hover:bg-slate-700 text-white font-bold rounded-xl transition-colors border border-white/5"
                        >
                             Cancel
                        </button>
                        <button 
                            onClick={() => verifyPasswordAndExecute(() => {
                                if (showConfirmModal === 'reset') onClearData();
                                if (showConfirmModal === 'downgrade' && onDowngrade) onDowngrade();
                            })}
                            className="py-3 bg-rose-600 hover:bg-rose-500 text-white font-bold rounded-xl shadow-[0_0_20px_rgba(244,63,94,0.4)] active:scale-95 transition-all flex items-center justify-center gap-2"
                        >
                             <Trash2 className="w-4 h-4" /> Confirm
                        </button>
                     </div>
                 </div>
             </div>
        </div>
      )}

    </div>
  );
};

export default Settings;

import React, { useMemo, useState } from 'react';
import { Account, UserPlan } from '../types';
import { TrendingUp, PieChart as PieChartIcon, DollarSign, Calculator, Building, Landmark, Percent, Heart, Briefcase } from 'lucide-react';
import { PieChart, Pie, Cell, Tooltip, ResponsiveContainer } from 'recharts';

interface InvestmentProps {
  accounts: Account[];
  formatCurrency: (amount: number) => string | React.ReactNode;
  userPlan: UserPlan;
}

const COLORS = ['#6366f1', '#ec4899', '#10b981', '#f59e0b', '#3b82f6', '#8b5cf6', '#06b6d4', '#f43f5e'];

const Investment: React.FC<InvestmentProps> = ({ accounts, formatCurrency, userPlan }) => {
  // Calculator State
  const [activeCalc, setActiveCalc] = useState<'compound' | 'ira' | 'insurance' | 'pension' | 'real_estate' | 'roi'>('compound');

  // Compound Input - Reset to 0
  const [compP, setCompP] = useState(0);
  const [compR, setCompR] = useState(0);
  const [compT, setCompT] = useState(0);
  const [compN, setCompN] = useState(12); // Frequency defaults to 12 (monthly) as it's a configuration, not user data

  // IRA Input - Reset to 0
  const [iraPV, setIraPV] = useState(0);
  const [iraC, setIraC] = useState(0);
  const [iraR, setIraR] = useState(0);
  const [iraT, setIraT] = useState(0);

  // Insurance Input - Reset to 0
  const [insIncome, setInsIncome] = useState(0);
  const [insYears, setInsYears] = useState(0);
  const [insDebt, setInsDebt] = useState(0);
  const [insHealth, setInsHealth] = useState<'excellent' | 'average' | 'poor'>('average');
  const [insTerm, setInsTerm] = useState(0);

  // Pension Input - Reset to 0
  const [penP0, setPenP0] = useState(0);
  const [penC, setPenC] = useState(0);
  const [penR, setPenR] = useState(0);
  const [penN, setPenN] = useState(0);
  const [penDrawN, setPenDrawN] = useState(0); 
  const [penDrawI, setPenDrawI] = useState(0); 

  // Real Estate Input - Reset to 0
  const [reRent, setReRent] = useState(0);
  const [rePrice, setRePrice] = useState(0);

  // ROI Input - Reset to 0
  const [roiInitial, setRoiInitial] = useState(0);
  const [roiFinal, setRoiFinal] = useState(0);
  const [roiCosts, setRoiCosts] = useState(0);

  const investmentAccounts = useMemo(() => {
    return accounts.filter(a => a.type === 'Investment');
  }, [accounts]);

  const totalPortfolioValue = useMemo(() => {
    return investmentAccounts.reduce((acc, curr) => acc + curr.balance, 0);
  }, [investmentAccounts]);

  const allocationData = useMemo(() => {
      if (investmentAccounts.length === 0) return [];
      return investmentAccounts.map(acc => ({
          name: acc.name,
          value: acc.balance
      })).sort((a, b) => b.value - a.value);
  }, [investmentAccounts]);

  // Logic Implementations
  const compoundResult = useMemo(() => {
      if (compP === 0) return 0;
      // A = P * (1 + r/n)^(n*t)
      const rDec = compR / 100;
      return compP * Math.pow((1 + rDec/compN), (compN * compT));
  }, [compP, compR, compN, compT]);

  const iraResult = useMemo(() => {
      if (iraPV === 0 && iraC === 0) return 0;
      // FV = PV * (1+r)^t + C * [((1+r)^t - 1) / r]
      const rDec = iraR / 100;
      const term1 = iraPV * Math.pow((1 + rDec), iraT);
      const term2 = rDec > 0 ? iraC * ((Math.pow((1 + rDec), iraT) - 1) / rDec) : iraC * iraT;
      return term1 + term2;
  }, [iraPV, iraR, iraC, iraT]);

  const insuranceResult = useMemo(() => {
      // Coverage = (Income * Years) + Debt
      const coverage = (insIncome * insYears) + insDebt;

      // Mock Premium Function f(Coverage, Term, Health)
      // Base: $0.5 per $1000 coverage/month
      let baseRate = (coverage / 1000) * 0.5;

      // Term Multiplier
      if (insTerm > 20) baseRate *= 1.5;
      else if (insTerm < 15) baseRate *= 0.8;

      // Health Multiplier
      if (insHealth === 'poor') baseRate *= 1.5;
      else if (insHealth === 'excellent') baseRate *= 0.8;

      return { coverage, premium: baseRate };
  }, [insIncome, insYears, insDebt, insHealth, insTerm]);

  const pensionResult = useMemo(() => {
      // Pot FV = P0(1+r)^n + C * [((1+r)^n - 1) / r]
      const rDec = penR / 100;
      const term1 = penP0 * Math.pow((1 + rDec), penN);
      const term2 = rDec > 0 ? penC * ((Math.pow((1 + rDec), penN) - 1) / rDec) : penC * penN;
      const fv = term1 + term2;

      // Drawdown Payment = FV * [ i / (1 - (1+i)^-N) ]
      const i = (penDrawI / 100) / 12;
      const payment = i > 0 && penDrawN > 0 ? fv * (i / (1 - Math.pow((1 + i), -penDrawN))) : (penDrawN > 0 ? fv / penDrawN : 0);

      return { fv, payment };
  }, [penP0, penC, penR, penN, penDrawN, penDrawI]);

  const realEstateResult = useMemo(() => {
      const annualRent = reRent * 12;
      const yieldVal = rePrice > 0 ? (annualRent / rePrice) * 100 : 0;
      return { annualRent, yieldVal };
  }, [reRent, rePrice]);

  const roiResult = useMemo(() => {
      const totalInv = roiInitial + roiCosts;
      const netProfit = roiFinal - totalInv;
      const roi = totalInv > 0 ? (netProfit / totalInv) * 100 : 0;
      return { netProfit, roi };
  }, [roiInitial, roiFinal, roiCosts]);

  return (
    <div className="space-y-8 animate-slide-up pb-20">
        <div className="flex justify-between items-end">
            <div>
                <div className="flex items-center gap-3 mb-2">
                    <h2 className="text-3xl font-black text-white tracking-tight flex items-center gap-3">
                        <TrendingUp className="w-8 h-8 text-emerald-400" />
                        Investment Node
                    </h2>
                    <span className="px-2 py-0.5 rounded bg-emerald-500/20 text-emerald-400 text-[10px] font-black tracking-widest border border-emerald-500/30 shadow-[0_0_10px_rgba(16,185,129,0.2)]">BETA</span>
                </div>
                <p className="text-slate-400 mt-2 font-medium">Portfolio metrics and projection engines.</p>
            </div>
        </div>

        {/* Portfolio Overview Cards */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="glass-card p-6 rounded-[2rem] border border-white/5 bg-slate-900/40 flex items-center justify-between">
                <div>
                    <div className="flex items-center gap-3 mb-2">
                        <div className="p-2 rounded-xl bg-emerald-500/10"><DollarSign className="w-5 h-5 text-emerald-400" /></div>
                        <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Total Valuation</span>
                    </div>
                    <div className="text-3xl font-black text-white tracking-tighter">{formatCurrency(totalPortfolioValue)}</div>
                </div>
            </div>

            <div className="glass-card p-6 rounded-[2rem] border border-white/5 bg-slate-900/40 flex items-center justify-between">
                <div>
                    <div className="flex items-center gap-3 mb-2">
                        <div className="p-2 rounded-xl bg-indigo-500/10"><PieChartIcon className="w-5 h-5 text-indigo-400" /></div>
                        <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Active Positions</span>
                    </div>
                    <div className="text-3xl font-black text-white tracking-tighter">{investmentAccounts.length}</div>
                </div>
            </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
            {/* Allocation Donut */}
            <div className="glass-card p-8 rounded-[2.5rem] border border-white/10 flex flex-col h-[400px]">
                <h3 className="text-lg font-bold text-white flex items-center gap-2 mb-6">
                    <PieChartIcon className="w-5 h-5 text-purple-400" /> Allocation
                </h3>

                <div className="flex-1 min-h-0 relative">
                    {allocationData.length > 0 ? (
                        <ResponsiveContainer width="100%" height="100%">
                            <PieChart>
                                <Pie
                                    data={allocationData}
                                    cx="50%"
                                    cy="50%"
                                    innerRadius={70}
                                    outerRadius={100}
                                    paddingAngle={5}
                                    dataKey="value"
                                >
                                    {allocationData.map((entry, index) => (
                                        <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                                    ))}
                                </Pie>
                                <Tooltip 
                                    contentStyle={{ backgroundColor: '#020617', border: '1px solid rgba(255,255,255,0.1)', borderRadius: '12px' }}
                                    itemStyle={{ color: '#fff', fontSize: '12px', fontWeight: 'bold' }}
                                    formatter={(val: number) => formatCurrency(val)}
                                />
                            </PieChart>
                        </ResponsiveContainer>
                    ) : (
                        <div className="absolute inset-0 flex flex-col items-center justify-center text-center opacity-50">
                            <div className="w-16 h-16 rounded-full bg-slate-800 flex items-center justify-center mb-3">
                                <PieChartIcon className="w-8 h-8 text-slate-500" />
                            </div>
                            <p className="text-xs font-bold text-slate-500 uppercase">No Investment Accounts</p>
                        </div>
                    )}
                </div>
            </div>

            {/* Assets List */}
            <div className="glass-card p-8 rounded-[2.5rem] border border-white/10 h-[400px] flex flex-col">
                <h3 className="text-lg font-bold text-white mb-6">Holdings</h3>
                <div className="overflow-y-auto custom-scrollbar flex-1 pr-2">
                    <table className="w-full text-left">
                        <thead className="text-[10px] font-black text-slate-500 uppercase tracking-widest border-b border-white/5 sticky top-0 bg-[#0f172a] z-10">
                            <tr>
                                <th className="pb-4 pl-2">Asset</th>
                                <th className="pb-4 text-right">Balance</th>
                                <th className="pb-4 text-right pr-2">Share</th>
                            </tr>
                        </thead>
                        <tbody className="text-sm">
                            {investmentAccounts.length > 0 ? (
                                investmentAccounts.map((acc, i) => (
                                    <tr key={acc.id} className="group border-b border-white/5 last:border-0 hover:bg-white/5 transition-colors">
                                        <td className="py-4 pl-2 font-bold text-white">
                                            <div className="flex items-center gap-3">
                                                <div className="w-2.5 h-2.5 rounded-full shrink-0" style={{ backgroundColor: COLORS[i % COLORS.length] }}></div>
                                                <div className="min-w-0">
                                                    <div className="truncate max-w-[120px]">{acc.name}</div>
                                                    <div className="text-[10px] text-slate-500 font-medium uppercase tracking-wider truncate max-w-[120px]">{acc.institution}</div>
                                                </div>
                                            </div>
                                        </td>
                                        <td className="py-4 text-right font-bold text-white">{formatCurrency(acc.balance)}</td>
                                        <td className="py-4 text-right pr-2 text-slate-400 font-medium">
                                            {totalPortfolioValue > 0 ? ((acc.balance / totalPortfolioValue) * 100).toFixed(1) : 0}%
                                        </td>
                                    </tr>
                                ))
                            ) : (
                                <tr>
                                    <td colSpan={3} className="py-8 text-center text-slate-500 font-medium text-xs">
                                        No investment accounts found.
                                    </td>
                                </tr>
                            )}
                        </tbody>
                    </table>
                </div>
            </div>
        </div>

        {/* Financial Logic Core (Calculators) */}
        <div className="glass-card p-8 rounded-[2.5rem] border border-white/10 bg-slate-900/20">
            <div className="flex items-center gap-3 mb-8">
                <div className="p-3 bg-indigo-600/20 rounded-xl text-indigo-400"><Calculator className="w-6 h-6" /></div>
                <div>
                    <h3 className="text-xl font-black text-white tracking-tight">Financial Logic Core</h3>
                    <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1">Projection Engines</p>
                </div>
            </div>

            <div className="flex gap-2 overflow-x-auto custom-scrollbar pb-4 mb-6">
                {[
                    { id: 'compound', label: 'Compound Interest', icon: <TrendingUp className="w-4 h-4" /> },
                    { id: 'ira', label: 'IRA Projector', icon: <Landmark className="w-4 h-4" /> },
                    { id: 'insurance', label: 'Life Insurance', icon: <Heart className="w-4 h-4" /> },
                    { id: 'pension', label: 'Pension Pot', icon: <Briefcase className="w-4 h-4" /> },
                    { id: 'real_estate', label: 'Real Estate Yield', icon: <Building className="w-4 h-4" /> },
                    { id: 'roi', label: 'ROI Calculator', icon: <Percent className="w-4 h-4" /> }
                ].map((item) => (
                    <button 
                        key={item.id}
                        onClick={() => setActiveCalc(item.id as any)}
                        className={`flex items-center gap-2 px-4 py-3 rounded-xl text-xs font-bold whitespace-nowrap transition-all ${activeCalc === item.id ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-600/20' : 'bg-slate-800 text-slate-400 hover:text-white hover:bg-slate-700'}`}
                    >
                        {item.icon} {item.label}
                    </button>
                ))}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 animate-fade-in">
                {/* Inputs Column */}
                <div className="space-y-5">
                    {activeCalc === 'compound' && (
                        <>
                            <InputGroup label="Principal (P)" value={compP} onChange={setCompP} prefix="$" />
                            <InputGroup label="Annual Rate (r)" value={compR} onChange={setCompR} suffix="%" />
                            <InputGroup label="Years (t)" value={compT} onChange={setCompT} suffix="yrs" />
                            <InputGroup label="Compounds / Year (n)" value={compN} onChange={setCompN} />
                        </>
                    )}
                    {activeCalc === 'ira' && (
                        <>
                            <InputGroup label="Current Savings (PV)" value={iraPV} onChange={setIraPV} prefix="$" />
                            <InputGroup label="Annual Contribution (C)" value={iraC} onChange={setIraC} prefix="$" />
                            <InputGroup label="Annual Return (r)" value={iraR} onChange={setIraR} suffix="%" />
                            <InputGroup label="Years to Retire (t)" value={iraT} onChange={setIraT} suffix="yrs" />
                        </>
                    )}
                    {activeCalc === 'insurance' && (
                        <>
                            <InputGroup label="Annual Income" value={insIncome} onChange={setInsIncome} prefix="$" />
                            <InputGroup label="Years Replacement" value={insYears} onChange={setInsYears} suffix="yrs" />
                            <InputGroup label="Total Debt" value={insDebt} onChange={setInsDebt} prefix="$" />
                            <InputGroup label="Policy Term" value={insTerm} onChange={setInsTerm} suffix="yrs" />
                            <div>
                                <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-1.5 block">Health Category</label>
                                <select value={insHealth} onChange={e => setInsHealth(e.target.value as any)} className="w-full bg-slate-950 border border-white/10 rounded-xl px-4 py-3 text-white text-sm focus:border-indigo-500 outline-none">
                                    <option value="excellent">Excellent</option>
                                    <option value="average">Average</option>
                                    <option value="poor">Poor</option>
                                </select>
                            </div>
                        </>
                    )}
                    {activeCalc === 'pension' && (
                        <>
                            <InputGroup label="Current Pot (P0)" value={penP0} onChange={setPenP0} prefix="$" />
                            <InputGroup label="Annual Contrib (C)" value={penC} onChange={setPenC} prefix="$" />
                            <InputGroup label="Growth Rate (r)" value={penR} onChange={setPenR} suffix="%" />
                            <InputGroup label="Years to Retire (n)" value={penN} onChange={setPenN} suffix="yrs" />
                            <div className="pt-4 border-t border-white/5">
                                <p className="text-[10px] font-black text-indigo-400 uppercase tracking-widest mb-3">Drawdown Settings</p>
                                <div className="grid grid-cols-2 gap-4">
                                    <InputGroup label="Months (N)" value={penDrawN} onChange={setPenDrawN} />
                                    <InputGroup label="Post-Retire Rate (i)" value={penDrawI} onChange={setPenDrawI} suffix="%" />
                                </div>
                            </div>
                        </>
                    )}
                    {activeCalc === 'real_estate' && (
                        <>
                            <InputGroup label="Monthly Rent" value={reRent} onChange={setReRent} prefix="$" />
                            <InputGroup label="Property Price" value={rePrice} onChange={setRePrice} prefix="$" />
                        </>
                    )}
                    {activeCalc === 'roi' && (
                        <>
                            <InputGroup label="Initial Investment" value={roiInitial} onChange={setRoiInitial} prefix="$" />
                            <InputGroup label="Final Value" value={roiFinal} onChange={setRoiFinal} prefix="$" />
                            <InputGroup label="Total Costs" value={roiCosts} onChange={setRoiCosts} prefix="$" />
                        </>
                    )}
                </div>

                {/* Results Column */}
                <div className="bg-slate-950/50 rounded-[2rem] border border-white/5 p-8 flex flex-col justify-center items-center text-center relative overflow-hidden">
                    <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-500/5 rounded-full blur-[80px]"></div>

                    {activeCalc === 'compound' && (
                        <>
                            <div className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] mb-2">Future Value (A)</div>
                            <div className="text-4xl font-black text-white tracking-tighter mb-4">{formatCurrency(compoundResult)}</div>
                            <p className="text-xs text-slate-400 font-medium max-w-xs">Projected total after {compT} years compounding {compN} times/year.</p>
                        </>
                    )}

                    {activeCalc === 'ira' && (
                        <>
                            <div className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] mb-2">Retirement Value (FV)</div>
                            <div className="text-4xl font-black text-emerald-400 tracking-tighter mb-4">{formatCurrency(iraResult)}</div>
                            <p className="text-xs text-slate-400 font-medium max-w-xs">Total accumulation at retirement based on annuity due growth.</p>
                        </>
                    )}

                    {activeCalc === 'insurance' && (
                        <>
                            <div className="mb-6 w-full">
                                <div className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] mb-1">Recommended Coverage</div>
                                <div className="text-3xl font-black text-white">{formatCurrency(insuranceResult.coverage)}</div>
                            </div>
                            <div className="w-full pt-6 border-t border-white/5">
                                <div className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] mb-1">Est. Monthly Premium</div>
                                <div className="text-2xl font-black text-indigo-400">~{formatCurrency(insuranceResult.premium)}/mo</div>
                                <p className="text-[9px] text-slate-500 mt-2 italic">Estimate only. Based on term & health factor.</p>
                            </div>
                        </>
                    )}

                    {activeCalc === 'pension' && (
                        <>
                            <div className="mb-6 w-full">
                                <div className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] mb-1">Projected Pot</div>
                                <div className="text-3xl font-black text-white">{formatCurrency(pensionResult.fv)}</div>
                            </div>
                            <div className="w-full pt-6 border-t border-white/5">
                                <div className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] mb-1">Est. Monthly Drawdown</div>
                                <div className="text-2xl font-black text-emerald-400">{formatCurrency(pensionResult.payment)}/mo</div>
                                <p className="text-[9px] text-slate-500 mt-2 italic">For {Math.floor(penDrawN/12)} years post-retirement.</p>
                            </div>
                        </>
                    )}

                    {activeCalc === 'real_estate' && (
                        <>
                            <div className="mb-6 w-full">
                                <div className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] mb-1">Annual Income</div>
                                <div className="text-3xl font-black text-white">{formatCurrency(realEstateResult.annualRent)}</div>
                            </div>
                            <div className="w-full pt-6 border-t border-white/5">
                                <div className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] mb-1">Gross Rental Yield</div>
                                <div className={`text-4xl font-black ${realEstateResult.yieldVal > 5 ? 'text-emerald-400' : 'text-amber-400'}`}>
                                    {realEstateResult.yieldVal.toFixed(2)}%
                                </div>
                            </div>
                        </>
                    )}

                    {activeCalc === 'roi' && (
                        <>
                            <div className="mb-6 w-full">
                                <div className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] mb-1">Net Profit/Loss</div>
                                <div className={`text-3xl font-black ${roiResult.netProfit >= 0 ? 'text-white' : 'text-rose-400'}`}>{formatCurrency(roiResult.netProfit)}</div>
                            </div>
                            <div className="w-full pt-6 border-t border-white/5">
                                <div className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em] mb-1">ROI Percentage</div>
                                <div className={`text-4xl font-black ${roiResult.roi >= 0 ? 'text-emerald-400' : 'text-rose-500'}`}>
                                    {roiResult.roi.toFixed(2)}%
                                </div>
                                <p className="text-[9px] text-slate-500 mt-2 font-bold uppercase">{roiResult.roi >= 0 ? 'Profitable' : 'Loss'}</p>
                            </div>
                        </>
                    )}
                </div>
            </div>
        </div>
    </div>
  );
};

