interface SmartMoneyProps {
  initialTab?: string;
  transactions: Transaction[];
  accounts: Account[];
  goals: Goal[];
  formatCurrency: (amount: number) => string | React.ReactNode;
  userPlan: UserPlan;
  onUpgradeClick: () => void;
  insightUsage: number;
  onIncrementUsage: (amount?: number) => void;
  negotiationUsage: number;
  onIncrementNegotiationUsage: () => void;
}

const SmartMoney: React.FC<SmartMoneyProps> = ({
  initialTab = 'cashflow',
  transactions,
  accounts,
  goals,
  formatCurrency,
  userPlan,
  onUpgradeClick,
  insightUsage,
  onIncrementUsage,
  negotiationUsage,
  onIncrementNegotiationUsage
}) => {
  const [activeTab, setActiveTab] = useState(initialTab);

  // Sync if initialTab prop changes (from parent navigation)
  useEffect(() => {
    if(initialTab) setActiveTab(initialTab);
  }, [initialTab]);

  return (
    <div className="h-full flex flex-col">
        {/* Navigation Header */}
        <div className="flex gap-3 mb-6 pb-2 overflow-x-auto custom-scrollbar">
            <button
                onClick={() => setActiveTab('cashflow')}
                className={`flex items-center gap-2 px-5 py-3 rounded-2xl text-xs font-bold uppercase tracking-wider transition-all whitespace-nowrap ${activeTab === 'cashflow' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20' : 'bg-slate-900/50 text-slate-500 hover:text-white hover:bg-slate-800 border border-white/5'}`}
            >
                <GitFork className="w-4 h-4" /> Cashflow Beta
            </button>
            <button
                onClick={() => setActiveTab('sandbox')}
                className={`flex items-center gap-2 px-5 py-3 rounded-2xl text-xs font-bold uppercase tracking-wider transition-all whitespace-nowrap ${activeTab === 'sandbox' ? 'bg-amber-600 text-white shadow-lg shadow-amber-500/20' : 'bg-slate-900/50 text-slate-500 hover:text-white hover:bg-slate-800 border border-white/5'}`}
            >
                <Microscope className="w-4 h-4" /> Predictive Sandbox
            </button>
            <button
                onClick={() => setActiveTab('negotiator')}
                className={`flex items-center gap-2 px-5 py-3 rounded-2xl text-xs font-bold uppercase tracking-wider transition-all whitespace-nowrap ${activeTab === 'negotiator' ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-500/20' : 'bg-slate-900/50 text-slate-500 hover:text-white hover:bg-slate-800 border border-white/5'}`}
            >
                <Handshake className="w-4 h-4" /> Negotiator
            </button>
        </div>

        {/* Content Area */}
        <div className="flex-1 animate-fade-in">
            {activeTab === 'cashflow' && (
                <CashflowBeta transactions={transactions} accounts={accounts} goals={goals} formatCurrency={formatCurrency} userPlan={userPlan} />
            )}
            {activeTab === 'sandbox' && (
                <ScenarioSandbox transactions={transactions} goals={goals} formatCurrency={formatCurrency} userPlan={userPlan} onUpgradeClick={onUpgradeClick} insightUsage={insightUsage} onIncrementUsage={onIncrementUsage} />
            )}
            {activeTab === 'negotiator' && (
                <BillNegotiator userPlan={userPlan} onIncrementUsage={onIncrementNegotiationUsage} negotiationUsage={negotiationUsage} transactions={transactions} />
            )}
        </div>
    </div>
  );
};

