  spendingPeriod
}) => {

    const netWorth = useMemo(() => accounts.reduce((acc, curr) => acc + curr.balance, 0), [accounts]);

    const currentMonthMetrics = useMemo(() => {
        const now = new Date();
        const currentMonth = now.getMonth();
        const currentYear = now.getFullYear();

        const income = transactions
            .filter(t => t.type === TransactionType.INCOME && new Date(t.date).getMonth() === currentMonth && new Date(t.date).getFullYear() === currentYear)
            .reduce((acc, t) => acc + t.amount, 0);

        const expense = transactions
            .filter(t => t.type === TransactionType.EXPENSE && new Date(t.date).getMonth() === currentMonth && new Date(t.date).getFullYear() === currentYear)
            .reduce((acc, t) => acc + t.amount, 0);

        return { income, expense };
    }, [transactions]);

    const chartData = useMemo(() => {
        const data = [];
        const now = new Date();
        const daysInMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();

        // Cumulative Calculation variables
        let accThis = 0;
        let accPrev = 0;

        for (let i = 1; i <= daysInMonth; i++) {
            const dateStr = new Date(now.getFullYear(), now.getMonth(), i).toLocaleDateString('en-US', { day: 'numeric' });

            // This month data
            const daySpend = transactions
                .filter(t => 
                    t.type === TransactionType.EXPENSE && 
                    new Date(t.date).getDate() === i && 
                    new Date(t.date).getMonth() === now.getMonth() &&
                    new Date(t.date).getFullYear() === now.getFullYear()
                )
                .reduce((acc, t) => acc + t.amount, 0);

            // Previous month comparison
            const prevMonthDate = new Date(now.getFullYear(), now.getMonth() - 1, i);
            const prevDaySpend = transactions
                .filter(t => 
                    t.type === TransactionType.EXPENSE && 
                    new Date(t.date).getDate() === i && 
                    new Date(t.date).getMonth() === prevMonthDate.getMonth() &&
                    new Date(t.date).getFullYear() === prevMonthDate.getFullYear()
                )
                .reduce((acc, t) => acc + t.amount, 0);

            accThis += daySpend;
            accPrev += prevDaySpend;

            // Only push data for days that have passed or are today for this month (avoid flat line into future if desired, but cumulative usually shows full month or up to today)
            // For a smoother chart, we can just show all days, or filter. Let's show all for now but maybe null out future days if needed.
            // Simplified: Show up to today for "ThisMonth" line to avoid flat line?
            // Let's just output data.

            const isFuture = i > now.getDate();

            data.push({
                name: dateStr,
                ThisMonth: isFuture ? null : accThis, // Don't plot future days for current month
                Comparison: accPrev
            });
        }
        return data;
    }, [transactions]);

    return (
        <div className="space-y-8 animate-slide-up pb-20">
