                        </div>
                        <div className="text-3xl font-black text-white tracking-tighter">
                            {formatCurrency(netWorth)}
                        </div>
                        <div className="mt-2 text-xs font-medium text-slate-500 flex items-center gap-1">
                            Total across {accounts.length} accounts
                        </div>
                    </div>
                </div>

                <div className="glass-card p-6 rounded-[2rem] border border-white/5 relative overflow-hidden group">
                    <div className="absolute top-0 right-0 w-32 h-32 bg-emerald-500/10 rounded-full blur-3xl -mr-16 -mt-16 group-hover:bg-emerald-500/20 transition-all"></div>
                    <div className="relative z-10">
                        <div className="flex items-center gap-2 mb-4">
                            <div className="p-2 bg-emerald-500/10 rounded-xl text-emerald-400"><TrendingUp className="w-5 h-5" /></div>
                            <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">Income (Mo)</span>
                        </div>
                        <div className="text-3xl font-black text-white tracking-tighter">
                            {formatCurrency(currentMonthMetrics.income)}
                        </div>
                    </div>
                </div>

                <div className="glass-card p-6 rounded-[2rem] border border-white/5 relative overflow-hidden group">
                    <div className="absolute top-0 right-0 w-32 h-32 bg-rose-500/10 rounded-full blur-3xl -mr-16 -mt-16 group-hover:bg-rose-500/20 transition-all"></div>
                    <div className="relative z-10">
                        <div className="flex items-center gap-2 mb-4">
                            <div className="p-2 bg-rose-500/10 rounded-xl text-rose-400"><TrendingDown className="w-5 h-5" /></div>
                            <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">Spent (Mo)</span>
                        </div>
                        <div className="text-3xl font-black text-white tracking-tighter">
                            {formatCurrency(currentMonthMetrics.expense)}
                        </div>
                    </div>
                </div>
            </div>

            {/* Spending Limit Enforcement Card */}
            <div className={`p-8 rounded-[2.5rem] border relative overflow-hidden transition-all ${spendingStatus === 'violation' ? 'bg-rose-950/30 border-rose-500/30' : spendingStatus === 'warning' ? 'bg-amber-950/30 border-amber-500/30' : 'bg-slate-900/40 border-white/10'}`}>
                <div className="flex justify-between items-start mb-6 relative z-10">
                    <div>
                        <h3 className="text-lg font-bold text-white flex items-center gap-2">
                            {spendingStatus === 'violation' ? <AlertTriangle className="w-5 h-5 text-rose-500" /> : <ShieldCheck className="w-5 h-5 text-emerald-500" />}
                            {spendingPeriod === 'weekly' ? 'Weekly' : 'Monthly'} Limit
                        </h3>
                        <p className="text-sm text-slate-400 mt-1 font-medium">
                            {spendingStatus === 'violation' ? 'Critical breach detected.' : spendingStatus === 'warning' ? 'Approaching threshold.' : 'Spending within parameters.'}
                        </p>
                    </div>
                    <div className="text-right">
                        <div className="text-2xl font-black text-white">{formatCurrency(currentPeriodSpend)}</div>
                        <div className="text-xs font-bold text-slate-500 uppercase tracking-wider">of {formatCurrency(spendingLimit)}</div>
                    </div>
                </div>

                <div className="w-full bg-slate-950/50 h-4 rounded-full overflow-hidden mb-2 relative z-10 border border-white/5">
                    <div 
                        className={`h-full rounded-full transition-all duration-1000 ${spendingStatus === 'violation' ? 'bg-rose-500' : spendingStatus === 'warning' ? 'bg-amber-500' : 'bg-emerald-500'}`} 
                        style={{ width: `${Math.min((currentPeriodSpend / spendingLimit) * 100, 100)}%` }}
                    >
                        {spendingStatus === 'violation' && <div className="absolute inset-0 bg-white/20 animate-pulse"></div>}
                    </div>
                </div>
            </div>

            {/* Chart Section */}
            <div className="glass-card p-8 rounded-[2.5rem] border border-white/10 relative overflow-hidden bg-slate-900/20 backdrop-blur-xl">
                <div className="flex justify-between items-center mb-8">
                    <h3 className="text-lg font-bold text-white flex items-center gap-2">
                        <Zap className="w-5 h-5 text-indigo-400" />
                        Spending Trajectory
                    </h3>
                    <div className="flex gap-4">
                        <div className="flex items-center gap-2">
                            <div className="w-3 h-3 bg-indigo-500 rounded-full"></div>
                            <span className="text-xs font-bold text-slate-400">Current</span>
                        </div>
                        <div className="flex items-center gap-2">
                            <div className="w-3 h-3 bg-slate-600 rounded-full"></div>
                            <span className="text-xs font-bold text-slate-400">Previous</span>
                        </div>
                    </div>
                </div>

                <div className="h-[300px] w-full">
                    <ResponsiveContainer width="100%" height="100%">
                        <ComposedChart data={chartData}>
                            <defs>
                                <linearGradient id="colorThisMonth" x1="0" y1="0" x2="0" y2="1">
                                    <stop offset="5%" stopColor="#6366f1" stopOpacity={0.3}/>
                                    <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                                </linearGradient>
                            </defs>
                            <CartesianGrid strokeDasharray="3 3" stroke="#1e293b" vertical={false} />
                            <XAxis 
                                dataKey="name" 
                                stroke="#64748b" 
                                fontSize={10} 
                                tickLine={false} 
                                axisLine={false} 
